window.ASTRYL_SHEET={"sun":{"head":"<div class=\"sheethead\"><img class=\"pimg\" src=\"img/planets/sun.webp\" alt=\"Sun\" width=\"600\" height=\"600\" loading=\"eager\" decoding=\"async\"><div><h2 id=\"sheetTitle\"><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Sun</span><span class=\"t\" lang=\"hi\">सूर्य</span><span class=\"t\" lang=\"es\">Sol</span><span class=\"t\" lang=\"pt\">Sol</span><span class=\"t\" lang=\"fr\">Soleil</span><span class=\"t\" lang=\"ar\">الشمس</span></h2><p class=\"sub\"><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Our star, the centre of the Solar System</span><span class=\"t\" lang=\"hi\">हमारा तारा, सौरमंडल का केंद्र</span><span class=\"t\" lang=\"es\">Nuestra estrella, el centro del sistema solar</span><span class=\"t\" lang=\"pt\">Nossa estrela, o centro do Sistema Solar</span><span class=\"t\" lang=\"fr\">Notre étoile, le centre du système solaire</span><span class=\"t\" lang=\"ar\">نجمنا، مركز المجموعة الشمسية</span></p></div></div>","body":"<div class=\"stats\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">1,392,700 km</span><span class=\"t\" lang=\"hi\">13,92,700 किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Diameter</span><span class=\"t\" lang=\"hi\">व्यास</span><span class=\"t\" lang=\"es\">Diámetro</span><span class=\"t\" lang=\"pt\">Diâmetro</span><span class=\"t\" lang=\"fr\">Diamètre</span><span class=\"t\" lang=\"ar\">القطر</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">274 m/s² (27.96 g)</span><span class=\"t\" lang=\"hi\">274 m/s² (27.96 g)</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Gravity</span><span class=\"t\" lang=\"hi\">गुरुत्वाकर्षण</span><span class=\"t\" lang=\"es\">Gravedad</span><span class=\"t\" lang=\"pt\">Gravidade</span><span class=\"t\" lang=\"fr\">Gravité</span><span class=\"t\" lang=\"ar\">الجاذبية</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">5,500 °C</span><span class=\"t\" lang=\"hi\">5,500 °C</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Average temperature</span><span class=\"t\" lang=\"hi\">औसत तापमान</span><span class=\"t\" lang=\"es\">Temperatura media</span><span class=\"t\" lang=\"pt\">Temperatura média</span><span class=\"t\" lang=\"fr\">Température moyenne</span><span class=\"t\" lang=\"ar\">متوسط الحرارة</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">25.4 days</span><span class=\"t\" lang=\"hi\">25.4 दिन</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Day</span><span class=\"t\" lang=\"hi\">दिन</span><span class=\"t\" lang=\"es\">Día</span><span class=\"t\" lang=\"pt\">Dia</span><span class=\"t\" lang=\"fr\">Jour</span><span class=\"t\" lang=\"ar\">اليوم</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">–</span><span class=\"t\" lang=\"hi\">–</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Year</span><span class=\"t\" lang=\"hi\">वर्ष</span><span class=\"t\" lang=\"es\">Año</span><span class=\"t\" lang=\"pt\">Ano</span><span class=\"t\" lang=\"fr\">Année</span><span class=\"t\" lang=\"ar\">السنة</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">0</span><span class=\"t\" lang=\"hi\">0</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Known moons</span><span class=\"t\" lang=\"hi\">ज्ञात चंद्रमा</span><span class=\"t\" lang=\"es\">Lunas conocidas</span><span class=\"t\" lang=\"pt\">Luas conhecidas</span><span class=\"t\" lang=\"fr\">Lunes connues</span><span class=\"t\" lang=\"ar\">الأقمار المعروفة</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">–</span><span class=\"t\" lang=\"hi\">–</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Distance from the Sun</span><span class=\"t\" lang=\"hi\">सूर्य से दूरी</span><span class=\"t\" lang=\"es\">Distancia al Sol</span><span class=\"t\" lang=\"pt\">Distância do Sol</span><span class=\"t\" lang=\"fr\">Distance du Soleil</span><span class=\"t\" lang=\"ar\">البعد عن الشمس</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">No solid surface</span><span class=\"t\" lang=\"hi\">कोई ठोस सतह नहीं</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Surface pressure</span><span class=\"t\" lang=\"hi\">सतह का दबाव</span><span class=\"t\" lang=\"es\">Presión en la superficie</span><span class=\"t\" lang=\"pt\">Pressão na superfície</span><span class=\"t\" lang=\"fr\">Pression à la surface</span><span class=\"t\" lang=\"ar\">الضغط على السطح</span></span></div></div><h3><span class=\"t\" lang=\"en\">When and how it formed</span><span class=\"t\" lang=\"hi\">कब और कैसे बना</span></h3><div class=\"formhead\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">About 4.6 billion years ago</span><span class=\"t\" lang=\"hi\">लगभग 4.6 अरब साल पहले</span></b><span><span class=\"t\" lang=\"en\">Formed</span><span class=\"t\" lang=\"hi\">कब बना</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">About 50 million years to start shining steadily</span><span class=\"t\" lang=\"hi\">स्थिर रूप से चमकने में लगभग 5 करोड़ साल</span></b><span><span class=\"t\" lang=\"en\">How long it took</span><span class=\"t\" lang=\"hi\">कितना समय लगा</span></span></div></div><p><span class=\"t\" lang=\"en\">A small part of a huge cloud of gas and dust collapsed under its own gravity, perhaps pushed by the blast of a nearby exploding star. The centre grew hot and dense until hydrogen began to fuse into helium. Everything else in the solar system formed from the flat, spinning disk left around it.</span><span class=\"t\" lang=\"hi\">गैस और धूल के एक विशाल बादल का एक छोटा हिस्सा अपनी ही gravity से सिकुड़ गया, शायद पास के किसी फटते तारे के धक्के से। केंद्र इतना गर्म और घना हो गया कि hydrogen जुड़कर helium बनने लगी। सौरमंडल की बाकी हर चीज़ उसके चारों ओर बची चपटी, घूमती disk से बनी।</span></p><div class=\"tl formtl\"><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">4.6 billion years ago</span><span class=\"t\" lang=\"hi\">4.6 अरब साल पहले</span></div><p><span class=\"t\" lang=\"en\">The cloud collapses; the oldest solid grains in meteorites date from this moment (4.567 billion years).</span><span class=\"t\" lang=\"hi\">बादल सिकुड़ता है; उल्कापिंडों के सबसे पुराने ठोस कण इसी समय के हैं (4.567 अरब साल)।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">First 100,000 years</span><span class=\"t\" lang=\"hi\">पहले 1 लाख साल</span></div><p><span class=\"t\" lang=\"en\">A glowing young star (a protostar) forms in the centre, wrapped in a disk of gas and dust.</span><span class=\"t\" lang=\"hi\">केंद्र में एक चमकता नया तारा (protostar) बनता है, गैस और धूल की disk में लिपटा हुआ।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">About 50 million years later</span><span class=\"t\" lang=\"hi\">लगभग 5 करोड़ साल बाद</span></div><p><span class=\"t\" lang=\"en\">Hydrogen fusion starts in the core and the Sun becomes a steady, grown-up star.</span><span class=\"t\" lang=\"hi\">केंद्र में hydrogen fusion शुरू होता है और सूरज एक स्थिर, पूरा तारा बन जाता है।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Today</span><span class=\"t\" lang=\"hi\">आज</span></div><p><span class=\"t\" lang=\"en\">About halfway through its life; it is about 30% brighter than when it was young.</span><span class=\"t\" lang=\"hi\">अपनी उम्र के लगभग बीच में; यह अपनी जवानी से लगभग 30% ज़्यादा चमकीला है।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">In about 5 billion years</span><span class=\"t\" lang=\"hi\">लगभग 5 अरब साल बाद</span></div><p><span class=\"t\" lang=\"en\">It swells into a red giant, then shrinks into a white dwarf.</span><span class=\"t\" lang=\"hi\">यह फूलकर red giant बनेगा, फिर सिकुड़कर white dwarf बन जाएगा।</span></p></div></div><p class=\"note\"><span class=\"t\" lang=\"en\">All dates are estimates from meteorites, moon rocks, space missions and computer models.</span><span class=\"t\" lang=\"hi\">सभी तारीख़ें अनुमान हैं, जो उल्कापिंडों, चाँद की चट्टानों, अंतरिक्ष missions और computer models से आती हैं।</span></p><h3><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Did you know?</span><span class=\"t\" lang=\"hi\">क्या आप जानते हैं?</span><span class=\"t\" lang=\"es\">¿Sabías que…?</span><span class=\"t\" lang=\"pt\">Você sabia?</span><span class=\"t\" lang=\"fr\">Le saviez-vous ?</span><span class=\"t\" lang=\"ar\">هل تعلم؟</span></h3><ul class=\"sheetfacts\"><li><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">The Sun holds 99.8% of all the mass in the solar system.</span><span class=\"t\" lang=\"hi\">सौरमंडल के कुल द्रव्यमान का 99.8% हिस्सा सूर्य में है।</span><span class=\"t\" lang=\"es\">El Sol contiene el 99,8 % de toda la masa del sistema solar.</span><span class=\"t\" lang=\"pt\">O Sol tem 99,8% de toda a massa do Sistema Solar.</span><span class=\"t\" lang=\"fr\">Le Soleil contient 99,8 % de toute la masse du système solaire.</span><span class=\"t\" lang=\"ar\">تحتوي الشمس على 99.8٪ من كتلة المجموعة الشمسية كلها.</span></li><li><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Sunlight takes about 8 minutes and 20 seconds to reach Earth.</span><span class=\"t\" lang=\"hi\">सूर्य की रोशनी को पृथ्वी तक पहुँचने में करीब 8 मिनट 20 सेकंड लगते हैं।</span><span class=\"t\" lang=\"es\">La luz del Sol tarda unos 8 minutos y 20 segundos en llegar a la Tierra.</span><span class=\"t\" lang=\"pt\">A luz do Sol leva cerca de 8 minutos e 20 segundos para chegar à Terra.</span><span class=\"t\" lang=\"fr\">La lumière du Soleil met environ 8 minutes et 20 secondes à atteindre la Terre.</span><span class=\"t\" lang=\"ar\">يستغرق ضوء الشمس نحو 8 دقائق و20 ثانية ليصل إلى الأرض.</span></li></ul><p><a class=\"btn primary\" href=\"body/sun.html\" data-full><span class=\"t\" lang=\"en\">Full page: layers, telescope view, atmosphere</span><span class=\"t\" lang=\"hi\">पूरा page: परतें, दूरबीन का दृश्य, वायुमंडल</span> →</a></p>"},"mercury":{"head":"<div class=\"sheethead\"><img class=\"pimg\" src=\"img/planets/mercury.webp\" alt=\"Mercury\" width=\"600\" height=\"600\" loading=\"eager\" decoding=\"async\"><div><h2 id=\"sheetTitle\"><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Mercury</span><span class=\"t\" lang=\"hi\">बुध</span><span class=\"t\" lang=\"es\">Mercurio</span><span class=\"t\" lang=\"pt\">Mercúrio</span><span class=\"t\" lang=\"fr\">Mercure</span><span class=\"t\" lang=\"ar\">عطارد</span></h2><p class=\"sub\"><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Planet 1 from the Sun</span><span class=\"t\" lang=\"hi\">सूर्य से ग्रह क्रमांक 1</span><span class=\"t\" lang=\"es\">Planeta 1 desde el Sol</span><span class=\"t\" lang=\"pt\">Planeta 1 a partir do Sol</span><span class=\"t\" lang=\"fr\">Planète 1 à partir du Soleil</span><span class=\"t\" lang=\"ar\">الكوكب 1 من الشمس</span></p></div></div>","body":"<div class=\"stats\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">4,879 km</span><span class=\"t\" lang=\"hi\">4,879 किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Diameter</span><span class=\"t\" lang=\"hi\">व्यास</span><span class=\"t\" lang=\"es\">Diámetro</span><span class=\"t\" lang=\"pt\">Diâmetro</span><span class=\"t\" lang=\"fr\">Diamètre</span><span class=\"t\" lang=\"ar\">القطر</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">3.7 m/s² (0.38 g)</span><span class=\"t\" lang=\"hi\">3.7 m/s² (0.38 g)</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Gravity</span><span class=\"t\" lang=\"hi\">गुरुत्वाकर्षण</span><span class=\"t\" lang=\"es\">Gravedad</span><span class=\"t\" lang=\"pt\">Gravidade</span><span class=\"t\" lang=\"fr\">Gravité</span><span class=\"t\" lang=\"ar\">الجاذبية</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">167 °C</span><span class=\"t\" lang=\"hi\">167 °C</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Average temperature</span><span class=\"t\" lang=\"hi\">औसत तापमान</span><span class=\"t\" lang=\"es\">Temperatura media</span><span class=\"t\" lang=\"pt\">Temperatura média</span><span class=\"t\" lang=\"fr\">Température moyenne</span><span class=\"t\" lang=\"ar\">متوسط الحرارة</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">175.9 days</span><span class=\"t\" lang=\"hi\">175.9 दिन</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Day</span><span class=\"t\" lang=\"hi\">दिन</span><span class=\"t\" lang=\"es\">Día</span><span class=\"t\" lang=\"pt\">Dia</span><span class=\"t\" lang=\"fr\">Jour</span><span class=\"t\" lang=\"ar\">اليوم</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">88 days</span><span class=\"t\" lang=\"hi\">88 दिन</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Year</span><span class=\"t\" lang=\"hi\">वर्ष</span><span class=\"t\" lang=\"es\">Año</span><span class=\"t\" lang=\"pt\">Ano</span><span class=\"t\" lang=\"fr\">Année</span><span class=\"t\" lang=\"ar\">السنة</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">0</span><span class=\"t\" lang=\"hi\">0</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Known moons</span><span class=\"t\" lang=\"hi\">ज्ञात चंद्रमा</span><span class=\"t\" lang=\"es\">Lunas conocidas</span><span class=\"t\" lang=\"pt\">Luas conhecidas</span><span class=\"t\" lang=\"fr\">Lunes connues</span><span class=\"t\" lang=\"ar\">الأقمار المعروفة</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">57.9 million km</span><span class=\"t\" lang=\"hi\">57.9 मिलियन किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Distance from the Sun</span><span class=\"t\" lang=\"hi\">सूर्य से दूरी</span><span class=\"t\" lang=\"es\">Distancia al Sol</span><span class=\"t\" lang=\"pt\">Distância do Sol</span><span class=\"t\" lang=\"fr\">Distance du Soleil</span><span class=\"t\" lang=\"ar\">البعد عن الشمس</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">≈ 0 bar</span><span class=\"t\" lang=\"hi\">≈ 0 bar</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Surface pressure</span><span class=\"t\" lang=\"hi\">सतह का दबाव</span><span class=\"t\" lang=\"es\">Presión en la superficie</span><span class=\"t\" lang=\"pt\">Pressão na superfície</span><span class=\"t\" lang=\"fr\">Pression à la surface</span><span class=\"t\" lang=\"ar\">الضغط على السطح</span></span></div></div><h3><span class=\"t\" lang=\"en\">When and how it formed</span><span class=\"t\" lang=\"hi\">कब और कैसे बना</span></h3><div class=\"formhead\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">About 4.6 billion years ago</span><span class=\"t\" lang=\"hi\">लगभग 4.6 अरब साल पहले</span></b><span><span class=\"t\" lang=\"en\">Formed</span><span class=\"t\" lang=\"hi\">कब बना</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">Probably a few tens of millions of years</span><span class=\"t\" lang=\"hi\">शायद कुछ करोड़ साल</span></b><span><span class=\"t\" lang=\"en\">How long it took</span><span class=\"t\" lang=\"hi\">कितना समय लगा</span></span></div></div><p><span class=\"t\" lang=\"en\">Rocky grains near the hot young Sun stuck together into bigger and bigger bodies that crashed and merged. Mercury ended up with a giant iron core that fills most of the planet.</span><span class=\"t\" lang=\"hi\">गर्म नए सूरज के पास पथरीले कण आपस में चिपककर बड़े और बड़े टुकड़े बने, जो टकराकर जुड़ते गए। बुध के पास एक विशाल लोहे का केंद्र बचा जो ग्रह का ज़्यादातर हिस्सा भरता है।</span></p><div class=\"tl formtl\"><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">4.6 billion years ago</span><span class=\"t\" lang=\"hi\">4.6 अरब साल पहले</span></div><p><span class=\"t\" lang=\"en\">Dust and rock near the Sun clump into small planet seeds.</span><span class=\"t\" lang=\"hi\">सूरज के पास धूल और चट्टान जुड़कर छोटे ग्रह-बीज बनते हैं।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">First tens of millions of years</span><span class=\"t\" lang=\"hi\">पहले कुछ करोड़ साल</span></div><p><span class=\"t\" lang=\"en\">The seeds collide and merge into Mercury; heavy iron sinks to the centre.</span><span class=\"t\" lang=\"hi\">बीज टकराकर बुध बनाते हैं; भारी लोहा केंद्र में डूब जाता है।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">About 4.1 to 3.8 billion years ago</span><span class=\"t\" lang=\"hi\">लगभग 4.1 से 3.8 अरब साल पहले</span></div><p><span class=\"t\" lang=\"en\">Big impacts and lava floods shape the surface; huge basins like Caloris form.</span><span class=\"t\" lang=\"hi\">बड़ी टक्करें और लावा की बाढ़ सतह बनाती हैं; Caloris जैसे विशाल गड्ढे बनते हैं।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Since then</span><span class=\"t\" lang=\"hi\">तब से</span></div><p><span class=\"t\" lang=\"en\">The planet slowly cools and shrinks, wrinkling its crust into long cliffs.</span><span class=\"t\" lang=\"hi\">ग्रह धीरे-धीरे ठंडा होकर सिकुड़ता है, जिससे उसकी परत पर लंबी चट्टानी झुर्रियाँ बनती हैं।</span></p></div></div><div class=\"callout\">❓ <b><span class=\"t\" lang=\"en\">Still unknown</span><span class=\"t\" lang=\"hi\">अभी भी अनजाना</span>:</b> <span class=\"t\" lang=\"en\">Why is the iron core so big? A giant impact may have knocked away much of the rocky outer layer, but MESSENGER found easily-lost elements like sulfur and potassium on the surface, which a very violent past would have boiled away.</span><span class=\"t\" lang=\"hi\">लोहे का केंद्र इतना बड़ा क्यों है? शायद एक बड़ी टक्कर ने बाहरी पथरीली परत का बड़ा हिस्सा उड़ा दिया, पर MESSENGER को सतह पर sulfur और potassium जैसे तत्व मिले जो इतने हिंसक अतीत में उड़ जाने चाहिए थे।</span></div><p class=\"note\"><span class=\"t\" lang=\"en\">All dates are estimates from meteorites, moon rocks, space missions and computer models.</span><span class=\"t\" lang=\"hi\">सभी तारीख़ें अनुमान हैं, जो उल्कापिंडों, चाँद की चट्टानों, अंतरिक्ष missions और computer models से आती हैं।</span></p><h3><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Did you know?</span><span class=\"t\" lang=\"hi\">क्या आप जानते हैं?</span><span class=\"t\" lang=\"es\">¿Sabías que…?</span><span class=\"t\" lang=\"pt\">Você sabia?</span><span class=\"t\" lang=\"fr\">Le saviez-vous ?</span><span class=\"t\" lang=\"ar\">هل تعلم؟</span></h3><ul class=\"sheetfacts\"><li><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">One day on Mercury, from sunrise to the next sunrise, lasts about 176 Earth days. That is twice as long as its year.</span><span class=\"t\" lang=\"hi\">बुध पर एक दिन, यानी एक सूर्योदय से अगले सूर्योदय तक, करीब 176 पृथ्वी-दिनों का होता है। यह उसके साल से दोगुना लंबा है।</span><span class=\"t\" lang=\"es\">Un día en Mercurio, de un amanecer al siguiente, dura unos 176 días terrestres. Es el doble que su año.</span><span class=\"t\" lang=\"pt\">Um dia em Mercúrio, de um nascer do Sol ao seguinte, dura cerca de 176 dias terrestres. É o dobro do seu ano.</span><span class=\"t\" lang=\"fr\">Un jour sur Mercure, d&#x27;un lever de soleil au suivant, dure environ 176 jours terrestres. C&#x27;est deux fois plus que son année.</span><span class=\"t\" lang=\"ar\">يستمر اليوم على عطارد، من شروق إلى الشروق التالي، نحو 176 يومًا أرضيًا. أي ضعف طول سنته.</span></li><li><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Mercury has almost no air, so its sky is black even by day, and its nights are freezing cold.</span><span class=\"t\" lang=\"hi\">बुध पर हवा लगभग नहीं है, इसलिए दिन में भी उसका आसमान काला रहता है और रातें बर्फ़ जैसी ठंडी होती हैं।</span><span class=\"t\" lang=\"es\">Mercurio casi no tiene aire, así que su cielo es negro incluso de día y sus noches son gélidas.</span><span class=\"t\" lang=\"pt\">Mercúrio quase não tem ar, então seu céu é preto mesmo de dia, e as noites são congelantes.</span><span class=\"t\" lang=\"fr\">Mercure n&#x27;a presque pas d&#x27;air, donc son ciel est noir même de jour, et ses nuits sont glaciales.</span><span class=\"t\" lang=\"ar\">لا هواء تقريبًا على عطارد، فسماؤه سوداء حتى في النهار، ولياليه شديدة البرودة.</span></li></ul><p><a class=\"btn primary\" href=\"body/mercury.html\" data-full><span class=\"t\" lang=\"en\">Full page: layers, telescope view, atmosphere</span><span class=\"t\" lang=\"hi\">पूरा page: परतें, दूरबीन का दृश्य, वायुमंडल</span> →</a></p>"},"venus":{"head":"<div class=\"sheethead\"><img class=\"pimg\" src=\"img/planets/venus.webp\" alt=\"Venus\" width=\"600\" height=\"600\" loading=\"eager\" decoding=\"async\"><div><h2 id=\"sheetTitle\"><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Venus</span><span class=\"t\" lang=\"hi\">शुक्र</span><span class=\"t\" lang=\"es\">Venus</span><span class=\"t\" lang=\"pt\">Vênus</span><span class=\"t\" lang=\"fr\">Vénus</span><span class=\"t\" lang=\"ar\">الزهرة</span></h2><p class=\"sub\"><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Planet 2 from the Sun</span><span class=\"t\" lang=\"hi\">सूर्य से ग्रह क्रमांक 2</span><span class=\"t\" lang=\"es\">Planeta 2 desde el Sol</span><span class=\"t\" lang=\"pt\">Planeta 2 a partir do Sol</span><span class=\"t\" lang=\"fr\">Planète 2 à partir du Soleil</span><span class=\"t\" lang=\"ar\">الكوكب 2 من الشمس</span></p></div></div>","body":"<div class=\"stats\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">12,104 km</span><span class=\"t\" lang=\"hi\">12,104 किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Diameter</span><span class=\"t\" lang=\"hi\">व्यास</span><span class=\"t\" lang=\"es\">Diámetro</span><span class=\"t\" lang=\"pt\">Diâmetro</span><span class=\"t\" lang=\"fr\">Diamètre</span><span class=\"t\" lang=\"ar\">القطر</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">8.9 m/s² (0.91 g)</span><span class=\"t\" lang=\"hi\">8.9 m/s² (0.91 g)</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Gravity</span><span class=\"t\" lang=\"hi\">गुरुत्वाकर्षण</span><span class=\"t\" lang=\"es\">Gravedad</span><span class=\"t\" lang=\"pt\">Gravidade</span><span class=\"t\" lang=\"fr\">Gravité</span><span class=\"t\" lang=\"ar\">الجاذبية</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">464 °C</span><span class=\"t\" lang=\"hi\">464 °C</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Average temperature</span><span class=\"t\" lang=\"hi\">औसत तापमान</span><span class=\"t\" lang=\"es\">Temperatura media</span><span class=\"t\" lang=\"pt\">Temperatura média</span><span class=\"t\" lang=\"fr\">Température moyenne</span><span class=\"t\" lang=\"ar\">متوسط الحرارة</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">116.8 days</span><span class=\"t\" lang=\"hi\">116.8 दिन</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Day</span><span class=\"t\" lang=\"hi\">दिन</span><span class=\"t\" lang=\"es\">Día</span><span class=\"t\" lang=\"pt\">Dia</span><span class=\"t\" lang=\"fr\">Jour</span><span class=\"t\" lang=\"ar\">اليوم</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">224.7 days</span><span class=\"t\" lang=\"hi\">224.7 दिन</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Year</span><span class=\"t\" lang=\"hi\">वर्ष</span><span class=\"t\" lang=\"es\">Año</span><span class=\"t\" lang=\"pt\">Ano</span><span class=\"t\" lang=\"fr\">Année</span><span class=\"t\" lang=\"ar\">السنة</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">0</span><span class=\"t\" lang=\"hi\">0</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Known moons</span><span class=\"t\" lang=\"hi\">ज्ञात चंद्रमा</span><span class=\"t\" lang=\"es\">Lunas conocidas</span><span class=\"t\" lang=\"pt\">Luas conhecidas</span><span class=\"t\" lang=\"fr\">Lunes connues</span><span class=\"t\" lang=\"ar\">الأقمار المعروفة</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">108.2 million km</span><span class=\"t\" lang=\"hi\">108.2 मिलियन किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Distance from the Sun</span><span class=\"t\" lang=\"hi\">सूर्य से दूरी</span><span class=\"t\" lang=\"es\">Distancia al Sol</span><span class=\"t\" lang=\"pt\">Distância do Sol</span><span class=\"t\" lang=\"fr\">Distance du Soleil</span><span class=\"t\" lang=\"ar\">البعد عن الشمس</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">92 bar</span><span class=\"t\" lang=\"hi\">92 bar</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Surface pressure</span><span class=\"t\" lang=\"hi\">सतह का दबाव</span><span class=\"t\" lang=\"es\">Presión en la superficie</span><span class=\"t\" lang=\"pt\">Pressão na superfície</span><span class=\"t\" lang=\"fr\">Pression à la surface</span><span class=\"t\" lang=\"ar\">الضغط على السطح</span></span></div></div><h3><span class=\"t\" lang=\"en\">When and how it formed</span><span class=\"t\" lang=\"hi\">कब और कैसे बना</span></h3><div class=\"formhead\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">About 4.6 billion years ago</span><span class=\"t\" lang=\"hi\">लगभग 4.6 अरब साल पहले</span></b><span><span class=\"t\" lang=\"en\">Formed</span><span class=\"t\" lang=\"hi\">कब बना</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">About as long as Earth, tens of millions of years</span><span class=\"t\" lang=\"hi\">पृथ्वी जितना ही, कुछ करोड़ साल</span></b><span><span class=\"t\" lang=\"en\">How long it took</span><span class=\"t\" lang=\"hi\">कितना समय लगा</span></span></div></div><p><span class=\"t\" lang=\"en\">Venus grew the same way as Earth and to almost the same size. Its story split from Earth&amp;#x27;s later: its air filled with carbon dioxide and trapped so much heat that any water boiled away.</span><span class=\"t\" lang=\"hi\">शुक्र पृथ्वी की तरह ही बना और लगभग उसी आकार का। उसकी कहानी बाद में अलग हुई: उसकी हवा carbon dioxide से भर गई और इतनी गर्मी फँसी कि सारा पानी उड़ गया।</span></p><div class=\"tl formtl\"><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">4.6 billion years ago</span><span class=\"t\" lang=\"hi\">4.6 अरब साल पहले</span></div><p><span class=\"t\" lang=\"en\">Rocky planet seeds merge into Venus, close to Earth&amp;#x27;s size.</span><span class=\"t\" lang=\"hi\">पथरीले ग्रह-बीज जुड़कर शुक्र बनाते हैं, लगभग पृथ्वी के आकार का।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Early on (unsure)</span><span class=\"t\" lang=\"hi\">शुरुआत में (पक्का नहीं)</span></div><p><span class=\"t\" lang=\"en\">It may have had shallow oceans while the young Sun was dimmer.</span><span class=\"t\" lang=\"hi\">जब नया सूरज कम चमकीला था, तब शायद यहाँ उथले समुद्र थे।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Later</span><span class=\"t\" lang=\"hi\">बाद में</span></div><p><span class=\"t\" lang=\"en\">A runaway greenhouse effect heats the planet; water escapes to space.</span><span class=\"t\" lang=\"hi\">बेकाबू greenhouse effect ग्रह को गर्म करता है; पानी अंतरिक्ष में उड़ जाता है।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">About 300 to 700 million years ago</span><span class=\"t\" lang=\"hi\">लगभग 30 से 70 करोड़ साल पहले</span></div><p><span class=\"t\" lang=\"en\">Lava covers most of the surface, so the ground we see is fairly young.</span><span class=\"t\" lang=\"hi\">लावा सतह के ज़्यादातर हिस्से को ढक देता है, इसलिए दिखने वाली ज़मीन काफ़ी नई है।</span></p></div></div><div class=\"callout\">❓ <b><span class=\"t\" lang=\"en\">Still unknown</span><span class=\"t\" lang=\"hi\">अभी भी अनजाना</span>:</b> <span class=\"t\" lang=\"en\">Did Venus ever have oceans, and for how long? Missions planned for the 2030s (VERITAS, DAVINCI, EnVision) are meant to find out.</span><span class=\"t\" lang=\"hi\">क्या शुक्र पर कभी समुद्र थे, और कितने समय तक? 2030 के दशक के missions (VERITAS, DAVINCI, EnVision) यही पता लगाएँगे।</span></div><p class=\"note\"><span class=\"t\" lang=\"en\">All dates are estimates from meteorites, moon rocks, space missions and computer models.</span><span class=\"t\" lang=\"hi\">सभी तारीख़ें अनुमान हैं, जो उल्कापिंडों, चाँद की चट्टानों, अंतरिक्ष missions और computer models से आती हैं।</span></p><h3><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Did you know?</span><span class=\"t\" lang=\"hi\">क्या आप जानते हैं?</span><span class=\"t\" lang=\"es\">¿Sabías que…?</span><span class=\"t\" lang=\"pt\">Você sabia?</span><span class=\"t\" lang=\"fr\">Le saviez-vous ?</span><span class=\"t\" lang=\"ar\">هل تعلم؟</span></h3><ul class=\"sheetfacts\"><li><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Venus spins backwards, so on Venus the Sun rises in the west.</span><span class=\"t\" lang=\"hi\">शुक्र उल्टी दिशा में घूमता है, इसलिए वहाँ सूरज पश्चिम में उगता है।</span><span class=\"t\" lang=\"es\">Venus gira al revés, así que en Venus el Sol sale por el oeste.</span><span class=\"t\" lang=\"pt\">Vênus gira ao contrário, então em Vênus o Sol nasce no oeste.</span><span class=\"t\" lang=\"fr\">Vénus tourne à l&#x27;envers, donc sur Vénus le Soleil se lève à l&#x27;ouest.</span><span class=\"t\" lang=\"ar\">تدور الزهرة بالاتجاه المعاكس، فتشرق الشمس على الزهرة من الغرب.</span></li><li><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Venus is hotter than Mercury, even though it is farther from the Sun, because its thick air traps the heat.</span><span class=\"t\" lang=\"hi\">सूर्य से ज़्यादा दूर होने पर भी शुक्र बुध से ज़्यादा गर्म है, क्योंकि उसकी घनी हवा गर्मी को रोक लेती है।</span><span class=\"t\" lang=\"es\">Venus es más caliente que Mercurio, aunque está más lejos del Sol, porque su aire denso atrapa el calor.</span><span class=\"t\" lang=\"pt\">Vênus é mais quente que Mercúrio, embora esteja mais longe do Sol, porque seu ar denso retém o calor.</span><span class=\"t\" lang=\"fr\">Vénus est plus chaude que Mercure, bien qu&#x27;elle soit plus loin du Soleil, car son air épais retient la chaleur.</span><span class=\"t\" lang=\"ar\">الزهرة أسخن من عطارد رغم أنها أبعد عن الشمس، لأن هواءها الكثيف يحبس الحرارة.</span></li></ul><p><a class=\"btn primary\" href=\"body/venus.html\" data-full><span class=\"t\" lang=\"en\">Full page: layers, telescope view, atmosphere</span><span class=\"t\" lang=\"hi\">पूरा page: परतें, दूरबीन का दृश्य, वायुमंडल</span> →</a></p>"},"earth":{"head":"<div class=\"sheethead\"><img class=\"pimg\" src=\"img/planets/earth.webp\" alt=\"Earth\" width=\"600\" height=\"600\" loading=\"eager\" decoding=\"async\"><div><h2 id=\"sheetTitle\"><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Earth</span><span class=\"t\" lang=\"hi\">पृथ्वी</span><span class=\"t\" lang=\"es\">Tierra</span><span class=\"t\" lang=\"pt\">Terra</span><span class=\"t\" lang=\"fr\">Terre</span><span class=\"t\" lang=\"ar\">الأرض</span></h2><p class=\"sub\"><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Planet 3 from the Sun</span><span class=\"t\" lang=\"hi\">सूर्य से ग्रह क्रमांक 3</span><span class=\"t\" lang=\"es\">Planeta 3 desde el Sol</span><span class=\"t\" lang=\"pt\">Planeta 3 a partir do Sol</span><span class=\"t\" lang=\"fr\">Planète 3 à partir du Soleil</span><span class=\"t\" lang=\"ar\">الكوكب 3 من الشمس</span></p></div></div>","body":"<div class=\"stats\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">12,756 km</span><span class=\"t\" lang=\"hi\">12,756 किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Diameter</span><span class=\"t\" lang=\"hi\">व्यास</span><span class=\"t\" lang=\"es\">Diámetro</span><span class=\"t\" lang=\"pt\">Diâmetro</span><span class=\"t\" lang=\"fr\">Diamètre</span><span class=\"t\" lang=\"ar\">القطر</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">9.8 m/s² (1 g)</span><span class=\"t\" lang=\"hi\">9.8 m/s² (1 g)</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Gravity</span><span class=\"t\" lang=\"hi\">गुरुत्वाकर्षण</span><span class=\"t\" lang=\"es\">Gravedad</span><span class=\"t\" lang=\"pt\">Gravidade</span><span class=\"t\" lang=\"fr\">Gravité</span><span class=\"t\" lang=\"ar\">الجاذبية</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">15 °C</span><span class=\"t\" lang=\"hi\">15 °C</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Average temperature</span><span class=\"t\" lang=\"hi\">औसत तापमान</span><span class=\"t\" lang=\"es\">Temperatura media</span><span class=\"t\" lang=\"pt\">Temperatura média</span><span class=\"t\" lang=\"fr\">Température moyenne</span><span class=\"t\" lang=\"ar\">متوسط الحرارة</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">24 h</span><span class=\"t\" lang=\"hi\">24 घंटे</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Day</span><span class=\"t\" lang=\"hi\">दिन</span><span class=\"t\" lang=\"es\">Día</span><span class=\"t\" lang=\"pt\">Dia</span><span class=\"t\" lang=\"fr\">Jour</span><span class=\"t\" lang=\"ar\">اليوم</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">365.2 days</span><span class=\"t\" lang=\"hi\">365.2 दिन</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Year</span><span class=\"t\" lang=\"hi\">वर्ष</span><span class=\"t\" lang=\"es\">Año</span><span class=\"t\" lang=\"pt\">Ano</span><span class=\"t\" lang=\"fr\">Année</span><span class=\"t\" lang=\"ar\">السنة</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">1</span><span class=\"t\" lang=\"hi\">1</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Known moons</span><span class=\"t\" lang=\"hi\">ज्ञात चंद्रमा</span><span class=\"t\" lang=\"es\">Lunas conocidas</span><span class=\"t\" lang=\"pt\">Luas conhecidas</span><span class=\"t\" lang=\"fr\">Lunes connues</span><span class=\"t\" lang=\"ar\">الأقمار المعروفة</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">149.6 million km</span><span class=\"t\" lang=\"hi\">149.6 मिलियन किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Distance from the Sun</span><span class=\"t\" lang=\"hi\">सूर्य से दूरी</span><span class=\"t\" lang=\"es\">Distancia al Sol</span><span class=\"t\" lang=\"pt\">Distância do Sol</span><span class=\"t\" lang=\"fr\">Distance du Soleil</span><span class=\"t\" lang=\"ar\">البعد عن الشمس</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">1 bar</span><span class=\"t\" lang=\"hi\">1 bar</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Surface pressure</span><span class=\"t\" lang=\"hi\">सतह का दबाव</span><span class=\"t\" lang=\"es\">Presión en la superficie</span><span class=\"t\" lang=\"pt\">Pressão na superfície</span><span class=\"t\" lang=\"fr\">Pression à la surface</span><span class=\"t\" lang=\"ar\">الضغط على السطح</span></span></div></div><h3><span class=\"t\" lang=\"en\">When and how it formed</span><span class=\"t\" lang=\"hi\">कब और कैसे बना</span></h3><div class=\"formhead\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">About 4.54 billion years ago</span><span class=\"t\" lang=\"hi\">लगभग 4.54 अरब साल पहले</span></b><span><span class=\"t\" lang=\"en\">Formed</span><span class=\"t\" lang=\"hi\">कब बना</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">About 30 to 100 million years</span><span class=\"t\" lang=\"hi\">लगभग 3 से 10 करोड़ साल</span></b><span><span class=\"t\" lang=\"en\">How long it took</span><span class=\"t\" lang=\"hi\">कितना समय लगा</span></span></div></div><p><span class=\"t\" lang=\"en\">Earth grew from rocky planet seeds that collided and merged. Heavy iron sank to form the core. A Mars-sized body called Theia then hit the young Earth, and the debris formed the Moon.</span><span class=\"t\" lang=\"hi\">पृथ्वी पथरीले ग्रह-बीजों के टकराने और जुड़ने से बनी। भारी लोहा डूबकर केंद्र बना। फिर मंगल जितना बड़ा एक पिंड, Theia, नई पृथ्वी से टकराया और उसके मलबे से चाँद बना।</span></p><div class=\"tl formtl\"><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">4.54 billion years ago</span><span class=\"t\" lang=\"hi\">4.54 अरब साल पहले</span></div><p><span class=\"t\" lang=\"en\">Planet seeds merge; Earth grows and heats up.</span><span class=\"t\" lang=\"hi\">ग्रह-बीज जुड़ते हैं; पृथ्वी बढ़ती और गर्म होती है।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">In the first ~30 million years</span><span class=\"t\" lang=\"hi\">पहले लगभग 3 करोड़ साल में</span></div><p><span class=\"t\" lang=\"en\">Iron sinks to the centre and forms the core.</span><span class=\"t\" lang=\"hi\">लोहा केंद्र में डूबकर core बनाता है।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">About 4.5 billion years ago</span><span class=\"t\" lang=\"hi\">लगभग 4.5 अरब साल पहले</span></div><p><span class=\"t\" lang=\"en\">The giant impact with Theia; the Moon forms from the debris.</span><span class=\"t\" lang=\"hi\">Theia से बड़ी टक्कर; मलबे से चाँद बनता है।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">About 4.4 billion years ago</span><span class=\"t\" lang=\"hi\">लगभग 4.4 अरब साल पहले</span></div><p><span class=\"t\" lang=\"en\">The oldest known crystals (zircons) show that liquid water already existed.</span><span class=\"t\" lang=\"hi\">सबसे पुराने ज्ञात क्रिस्टल (zircon) बताते हैं कि तब तक तरल पानी मौजूद था।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">At least 3.5 billion years ago</span><span class=\"t\" lang=\"hi\">कम से कम 3.5 अरब साल पहले</span></div><p><span class=\"t\" lang=\"en\">Life appears; about 2.4 billion years ago microbes fill the air with oxygen.</span><span class=\"t\" lang=\"hi\">जीवन आता है; लगभग 2.4 अरब साल पहले सूक्ष्म जीव हवा को oxygen से भर देते हैं।</span></p></div></div><p class=\"note\"><span class=\"t\" lang=\"en\">All dates are estimates from meteorites, moon rocks, space missions and computer models.</span><span class=\"t\" lang=\"hi\">सभी तारीख़ें अनुमान हैं, जो उल्कापिंडों, चाँद की चट्टानों, अंतरिक्ष missions और computer models से आती हैं।</span></p><h3><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Did you know?</span><span class=\"t\" lang=\"hi\">क्या आप जानते हैं?</span><span class=\"t\" lang=\"es\">¿Sabías que…?</span><span class=\"t\" lang=\"pt\">Você sabia?</span><span class=\"t\" lang=\"fr\">Le saviez-vous ?</span><span class=\"t\" lang=\"ar\">هل تعلم؟</span></h3><ul class=\"sheetfacts\"><li><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Earth is the only place we know with life, and about 71% of its surface is covered by water.</span><span class=\"t\" lang=\"hi\">पृथ्वी अकेली ऐसी जगह है जहाँ हम जीवन जानते हैं, और उसकी सतह का करीब 71% हिस्सा पानी से ढका है।</span><span class=\"t\" lang=\"es\">La Tierra es el único lugar donde sabemos que hay vida, y cerca del 71 % de su superficie está cubierta de agua.</span><span class=\"t\" lang=\"pt\">A Terra é o único lugar onde sabemos que há vida, e cerca de 71% da sua superfície é coberta de água.</span><span class=\"t\" lang=\"fr\">La Terre est le seul endroit où nous savons qu&#x27;il y a de la vie, et environ 71 % de sa surface est couverte d&#x27;eau.</span><span class=\"t\" lang=\"ar\">الأرض هي المكان الوحيد الذي نعرف فيه الحياة، ونحو 71٪ من سطحها مغطى بالماء.</span></li><li><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Earth is not a perfect ball. It bulges a little at the equator because it spins.</span><span class=\"t\" lang=\"hi\">पृथ्वी पूरी तरह गोल नहीं है। घूमने की वजह से वह भूमध्य रेखा पर थोड़ी उभरी हुई है।</span><span class=\"t\" lang=\"es\">La Tierra no es una bola perfecta. Se abulta un poco en el ecuador porque gira.</span><span class=\"t\" lang=\"pt\">A Terra não é uma bola perfeita. Ela é um pouco mais larga no equador porque gira.</span><span class=\"t\" lang=\"fr\">La Terre n&#x27;est pas une boule parfaite. Elle est un peu renflée à l&#x27;équateur parce qu&#x27;elle tourne.</span><span class=\"t\" lang=\"ar\">الأرض ليست كرة مثالية. فهي تنتفخ قليلًا عند خط الاستواء لأنها تدور.</span></li></ul><h3><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Major moons</span><span class=\"t\" lang=\"hi\">मुख्य चंद्रमा</span><span class=\"t\" lang=\"es\">Lunas principales</span><span class=\"t\" lang=\"pt\">Luas principais</span><span class=\"t\" lang=\"fr\">Lunes principales</span><span class=\"t\" lang=\"ar\">الأقمار الرئيسية</span></h3><div class=\"sheetmoons\"><a href=\"body/moon.html\"><img class=\"pimg\" src=\"img/planets/moon-s.webp\" alt=\"Moon\" width=\"160\" height=\"160\" loading=\"lazy\" decoding=\"async\"><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Moon</span><span class=\"t\" lang=\"hi\">चंद्रमा</span><span class=\"t\" lang=\"es\">Luna</span><span class=\"t\" lang=\"pt\">Lua</span><span class=\"t\" lang=\"fr\">Lune</span><span class=\"t\" lang=\"ar\">القمر</span></span></a></div><p><a class=\"btn primary\" href=\"body/earth.html\" data-full><span class=\"t\" lang=\"en\">Full page: layers, telescope view, atmosphere</span><span class=\"t\" lang=\"hi\">पूरा page: परतें, दूरबीन का दृश्य, वायुमंडल</span> →</a></p>"},"mars":{"head":"<div class=\"sheethead\"><img class=\"pimg\" src=\"img/planets/mars.webp\" alt=\"Mars\" width=\"600\" height=\"600\" loading=\"eager\" decoding=\"async\"><div><h2 id=\"sheetTitle\"><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Mars</span><span class=\"t\" lang=\"hi\">मंगल</span><span class=\"t\" lang=\"es\">Marte</span><span class=\"t\" lang=\"pt\">Marte</span><span class=\"t\" lang=\"fr\">Mars</span><span class=\"t\" lang=\"ar\">المريخ</span></h2><p class=\"sub\"><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Planet 4 from the Sun</span><span class=\"t\" lang=\"hi\">सूर्य से ग्रह क्रमांक 4</span><span class=\"t\" lang=\"es\">Planeta 4 desde el Sol</span><span class=\"t\" lang=\"pt\">Planeta 4 a partir do Sol</span><span class=\"t\" lang=\"fr\">Planète 4 à partir du Soleil</span><span class=\"t\" lang=\"ar\">الكوكب 4 من الشمس</span></p></div></div>","body":"<div class=\"stats\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">6,792 km</span><span class=\"t\" lang=\"hi\">6,792 किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Diameter</span><span class=\"t\" lang=\"hi\">व्यास</span><span class=\"t\" lang=\"es\">Diámetro</span><span class=\"t\" lang=\"pt\">Diâmetro</span><span class=\"t\" lang=\"fr\">Diamètre</span><span class=\"t\" lang=\"ar\">القطر</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">3.7 m/s² (0.38 g)</span><span class=\"t\" lang=\"hi\">3.7 m/s² (0.38 g)</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Gravity</span><span class=\"t\" lang=\"hi\">गुरुत्वाकर्षण</span><span class=\"t\" lang=\"es\">Gravedad</span><span class=\"t\" lang=\"pt\">Gravidade</span><span class=\"t\" lang=\"fr\">Gravité</span><span class=\"t\" lang=\"ar\">الجاذبية</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">-65 °C</span><span class=\"t\" lang=\"hi\">-65 °C</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Average temperature</span><span class=\"t\" lang=\"hi\">औसत तापमान</span><span class=\"t\" lang=\"es\">Temperatura media</span><span class=\"t\" lang=\"pt\">Temperatura média</span><span class=\"t\" lang=\"fr\">Température moyenne</span><span class=\"t\" lang=\"ar\">متوسط الحرارة</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">24.7 h</span><span class=\"t\" lang=\"hi\">24.7 घंटे</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Day</span><span class=\"t\" lang=\"hi\">दिन</span><span class=\"t\" lang=\"es\">Día</span><span class=\"t\" lang=\"pt\">Dia</span><span class=\"t\" lang=\"fr\">Jour</span><span class=\"t\" lang=\"ar\">اليوم</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">687 days</span><span class=\"t\" lang=\"hi\">687 दिन</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Year</span><span class=\"t\" lang=\"hi\">वर्ष</span><span class=\"t\" lang=\"es\">Año</span><span class=\"t\" lang=\"pt\">Ano</span><span class=\"t\" lang=\"fr\">Année</span><span class=\"t\" lang=\"ar\">السنة</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">2</span><span class=\"t\" lang=\"hi\">2</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Known moons</span><span class=\"t\" lang=\"hi\">ज्ञात चंद्रमा</span><span class=\"t\" lang=\"es\">Lunas conocidas</span><span class=\"t\" lang=\"pt\">Luas conhecidas</span><span class=\"t\" lang=\"fr\">Lunes connues</span><span class=\"t\" lang=\"ar\">الأقمار المعروفة</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">228 million km</span><span class=\"t\" lang=\"hi\">228 मिलियन किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Distance from the Sun</span><span class=\"t\" lang=\"hi\">सूर्य से दूरी</span><span class=\"t\" lang=\"es\">Distancia al Sol</span><span class=\"t\" lang=\"pt\">Distância do Sol</span><span class=\"t\" lang=\"fr\">Distance du Soleil</span><span class=\"t\" lang=\"ar\">البعد عن الشمس</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">0.006 bar</span><span class=\"t\" lang=\"hi\">0.006 bar</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Surface pressure</span><span class=\"t\" lang=\"hi\">सतह का दबाव</span><span class=\"t\" lang=\"es\">Presión en la superficie</span><span class=\"t\" lang=\"pt\">Pressão na superfície</span><span class=\"t\" lang=\"fr\">Pression à la surface</span><span class=\"t\" lang=\"ar\">الضغط على السطح</span></span></div></div><h3><span class=\"t\" lang=\"en\">When and how it formed</span><span class=\"t\" lang=\"hi\">कब और कैसे बना</span></h3><div class=\"formhead\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">About 4.6 billion years ago</span><span class=\"t\" lang=\"hi\">लगभग 4.6 अरब साल पहले</span></b><span><span class=\"t\" lang=\"en\">Formed</span><span class=\"t\" lang=\"hi\">कब बना</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">Fast: about 2 to 4 million years</span><span class=\"t\" lang=\"hi\">तेज़ी से: लगभग 20 से 40 लाख साल</span></b><span><span class=\"t\" lang=\"en\">How long it took</span><span class=\"t\" lang=\"hi\">कितना समय लगा</span></span></div></div><p><span class=\"t\" lang=\"en\">Mars formed quickly and then stopped growing, which is why it stayed small. Meteorites from Mars show its core formed only a few million years after the solar system began. It once had rivers and lakes, then lost its magnetic field and most of its air.</span><span class=\"t\" lang=\"hi\">मंगल तेज़ी से बना और फिर बढ़ना रुक गया, इसीलिए छोटा रह गया। मंगल से आए उल्कापिंड बताते हैं कि उसका core सौरमंडल शुरू होने के कुछ ही लाख साल बाद बन गया था। कभी यहाँ नदियाँ और झीलें थीं, फिर इसने अपना magnetic field और ज़्यादातर हवा खो दी।</span></p><div class=\"tl formtl\"><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">4.6 billion years ago</span><span class=\"t\" lang=\"hi\">4.6 अरब साल पहले</span></div><p><span class=\"t\" lang=\"en\">Mars grows to nearly full size within a few million years.</span><span class=\"t\" lang=\"hi\">कुछ ही लाख साल में मंगल लगभग पूरे आकार का हो जाता है।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">About 4.1 to 3.7 billion years ago</span><span class=\"t\" lang=\"hi\">लगभग 4.1 से 3.7 अरब साल पहले</span></div><p><span class=\"t\" lang=\"en\">A warmer, wetter time: rivers carve valleys and lakes fill craters like Jezero.</span><span class=\"t\" lang=\"hi\">गर्म, गीला समय: नदियाँ घाटियाँ काटती हैं और Jezero जैसे गड्ढों में झीलें भरती हैं।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">About 4 billion years ago</span><span class=\"t\" lang=\"hi\">लगभग 4 अरब साल पहले</span></div><p><span class=\"t\" lang=\"en\">Its global magnetic field fades; the solar wind strips away much of the air.</span><span class=\"t\" lang=\"hi\">उसका magnetic field कमज़ोर पड़ता है; सौर हवा ज़्यादातर हवा उड़ा ले जाती है।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Until recently</span><span class=\"t\" lang=\"hi\">हाल तक</span></div><p><span class=\"t\" lang=\"en\">Giant volcanoes like Olympus Mons erupt from time to time; today Mars is cold and dry.</span><span class=\"t\" lang=\"hi\">Olympus Mons जैसे विशाल ज्वालामुखी कभी-कभी फटते रहे; आज मंगल ठंडा और सूखा है।</span></p></div></div><div class=\"callout\">❓ <b><span class=\"t\" lang=\"en\">Still unknown</span><span class=\"t\" lang=\"hi\">अभी भी अनजाना</span>:</b> <span class=\"t\" lang=\"en\">Was early Mars warm for a long time or only in short bursts, and did life ever start there? Perseverance is collecting rock samples to help answer this.</span><span class=\"t\" lang=\"hi\">क्या शुरुआती मंगल लंबे समय तक गर्म था या बस थोड़े-थोड़े समय के लिए, और क्या वहाँ कभी जीवन शुरू हुआ? Perseverance इसके लिए चट्टानों के नमूने जमा कर रहा है।</span></div><p class=\"note\"><span class=\"t\" lang=\"en\">All dates are estimates from meteorites, moon rocks, space missions and computer models.</span><span class=\"t\" lang=\"hi\">सभी तारीख़ें अनुमान हैं, जो उल्कापिंडों, चाँद की चट्टानों, अंतरिक्ष missions और computer models से आती हैं।</span></p><h3><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Did you know?</span><span class=\"t\" lang=\"hi\">क्या आप जानते हैं?</span><span class=\"t\" lang=\"es\">¿Sabías que…?</span><span class=\"t\" lang=\"pt\">Você sabia?</span><span class=\"t\" lang=\"fr\">Le saviez-vous ?</span><span class=\"t\" lang=\"ar\">هل تعلم؟</span></h3><ul class=\"sheetfacts\"><li><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Olympus Mons on Mars is the tallest volcano in the solar system, about two and a half times as tall as Mount Everest.</span><span class=\"t\" lang=\"hi\">मंगल का ओलंपस मॉन्स सौरमंडल का सबसे ऊँचा ज्वालामुखी है, माउंट एवरेस्ट से करीब ढाई गुना ऊँचा।</span><span class=\"t\" lang=\"es\">El Monte Olimpo de Marte es el volcán más alto del sistema solar, unas dos veces y media la altura del Everest.</span><span class=\"t\" lang=\"pt\">O Monte Olimpo, em Marte, é o vulcão mais alto do Sistema Solar, cerca de duas vezes e meia a altura do Everest.</span><span class=\"t\" lang=\"fr\">Olympus Mons, sur Mars, est le plus haut volcan du système solaire, environ deux fois et demie la hauteur de l&#x27;Everest.</span><span class=\"t\" lang=\"ar\">أوليمبوس مونس على المريخ أعلى بركان في المجموعة الشمسية، وارتفاعه نحو مرتين ونصف ارتفاع إيفرست.</span></li><li><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Sunsets on Mars look blue.</span><span class=\"t\" lang=\"hi\">मंगल पर सूर्यास्त नीले दिखते हैं।</span><span class=\"t\" lang=\"es\">Los atardeceres en Marte se ven azules.</span><span class=\"t\" lang=\"pt\">Os pores do sol em Marte são azuis.</span><span class=\"t\" lang=\"fr\">Les couchers de soleil sur Mars sont bleus.</span><span class=\"t\" lang=\"ar\">غروب الشمس على المريخ يبدو أزرق.</span></li></ul><p><a class=\"btn primary\" href=\"body/mars.html\" data-full><span class=\"t\" lang=\"en\">Full page: layers, telescope view, atmosphere</span><span class=\"t\" lang=\"hi\">पूरा page: परतें, दूरबीन का दृश्य, वायुमंडल</span> →</a></p>"},"jupiter":{"head":"<div class=\"sheethead\"><img class=\"pimg\" src=\"img/planets/jupiter.webp\" alt=\"Jupiter\" width=\"600\" height=\"600\" loading=\"eager\" decoding=\"async\"><div><h2 id=\"sheetTitle\"><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Jupiter</span><span class=\"t\" lang=\"hi\">बृहस्पति</span><span class=\"t\" lang=\"es\">Júpiter</span><span class=\"t\" lang=\"pt\">Júpiter</span><span class=\"t\" lang=\"fr\">Jupiter</span><span class=\"t\" lang=\"ar\">المشتري</span></h2><p class=\"sub\"><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Planet 5 from the Sun</span><span class=\"t\" lang=\"hi\">सूर्य से ग्रह क्रमांक 5</span><span class=\"t\" lang=\"es\">Planeta 5 desde el Sol</span><span class=\"t\" lang=\"pt\">Planeta 5 a partir do Sol</span><span class=\"t\" lang=\"fr\">Planète 5 à partir du Soleil</span><span class=\"t\" lang=\"ar\">الكوكب 5 من الشمس</span></p></div></div>","body":"<div class=\"stats\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">142,984 km</span><span class=\"t\" lang=\"hi\">1,42,984 किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Diameter</span><span class=\"t\" lang=\"hi\">व्यास</span><span class=\"t\" lang=\"es\">Diámetro</span><span class=\"t\" lang=\"pt\">Diâmetro</span><span class=\"t\" lang=\"fr\">Diamètre</span><span class=\"t\" lang=\"ar\">القطر</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">23.1 m/s² (2.36 g)</span><span class=\"t\" lang=\"hi\">23.1 m/s² (2.36 g)</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Gravity</span><span class=\"t\" lang=\"hi\">गुरुत्वाकर्षण</span><span class=\"t\" lang=\"es\">Gravedad</span><span class=\"t\" lang=\"pt\">Gravidade</span><span class=\"t\" lang=\"fr\">Gravité</span><span class=\"t\" lang=\"ar\">الجاذبية</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">-110 °C</span><span class=\"t\" lang=\"hi\">-110 °C</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Average temperature</span><span class=\"t\" lang=\"hi\">औसत तापमान</span><span class=\"t\" lang=\"es\">Temperatura media</span><span class=\"t\" lang=\"pt\">Temperatura média</span><span class=\"t\" lang=\"fr\">Température moyenne</span><span class=\"t\" lang=\"ar\">متوسط الحرارة</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">9.9 h</span><span class=\"t\" lang=\"hi\">9.9 घंटे</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Day</span><span class=\"t\" lang=\"hi\">दिन</span><span class=\"t\" lang=\"es\">Día</span><span class=\"t\" lang=\"pt\">Dia</span><span class=\"t\" lang=\"fr\">Jour</span><span class=\"t\" lang=\"ar\">اليوم</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">11.9 years</span><span class=\"t\" lang=\"hi\">11.9 वर्ष</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Year</span><span class=\"t\" lang=\"hi\">वर्ष</span><span class=\"t\" lang=\"es\">Año</span><span class=\"t\" lang=\"pt\">Ano</span><span class=\"t\" lang=\"fr\">Année</span><span class=\"t\" lang=\"ar\">السنة</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">115</span><span class=\"t\" lang=\"hi\">115</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Known moons</span><span class=\"t\" lang=\"hi\">ज्ञात चंद्रमा</span><span class=\"t\" lang=\"es\">Lunas conocidas</span><span class=\"t\" lang=\"pt\">Luas conhecidas</span><span class=\"t\" lang=\"fr\">Lunes connues</span><span class=\"t\" lang=\"ar\">الأقمار المعروفة</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">778.5 million km</span><span class=\"t\" lang=\"hi\">778.5 मिलियन किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Distance from the Sun</span><span class=\"t\" lang=\"hi\">सूर्य से दूरी</span><span class=\"t\" lang=\"es\">Distancia al Sol</span><span class=\"t\" lang=\"pt\">Distância do Sol</span><span class=\"t\" lang=\"fr\">Distance du Soleil</span><span class=\"t\" lang=\"ar\">البعد عن الشمس</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">No solid surface</span><span class=\"t\" lang=\"hi\">कोई ठोस सतह नहीं</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Surface pressure</span><span class=\"t\" lang=\"hi\">सतह का दबाव</span><span class=\"t\" lang=\"es\">Presión en la superficie</span><span class=\"t\" lang=\"pt\">Pressão na superfície</span><span class=\"t\" lang=\"fr\">Pression à la surface</span><span class=\"t\" lang=\"ar\">الضغط على السطح</span></span></div></div><h3><span class=\"t\" lang=\"en\">When and how it formed</span><span class=\"t\" lang=\"hi\">कब और कैसे बना</span></h3><div class=\"formhead\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">About 4.6 billion years ago, the first planet</span><span class=\"t\" lang=\"hi\">लगभग 4.6 अरब साल पहले, सबसे पहला ग्रह</span></b><span><span class=\"t\" lang=\"en\">Formed</span><span class=\"t\" lang=\"hi\">कब बना</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">Its core in about 1 million years; the gas within a few million</span><span class=\"t\" lang=\"hi\">core लगभग 10 लाख साल में; गैस कुछ लाख साल में</span></b><span><span class=\"t\" lang=\"en\">How long it took</span><span class=\"t\" lang=\"hi\">कितना समय लगा</span></span></div></div><p><span class=\"t\" lang=\"en\">Beyond the &amp;quot;snow line&amp;quot;, where water froze into ice, a solid core grew quickly to many times Earth&amp;#x27;s mass. Its gravity then pulled in huge amounts of hydrogen and helium gas. Jupiter was the first planet, and its gravity shaped where the others could form.</span><span class=\"t\" lang=\"hi\">&amp;quot;snow line&amp;quot; के आगे, जहाँ पानी बर्फ़ बन जाता था, एक ठोस core तेज़ी से पृथ्वी से कई गुना भारी हो गया। फिर उसकी gravity ने भारी मात्रा में hydrogen और helium गैस खींच ली। बृहस्पति सबसे पहला ग्रह था, और उसकी gravity ने तय किया कि बाकी ग्रह कहाँ बन सकते थे।</span></p><div class=\"tl formtl\"><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">First ~1 million years</span><span class=\"t\" lang=\"hi\">पहले लगभग 10 लाख साल</span></div><p><span class=\"t\" lang=\"en\">A core of rock and ice grows to about 20 times Earth&amp;#x27;s mass.</span><span class=\"t\" lang=\"hi\">चट्टान और बर्फ़ का core पृथ्वी से लगभग 20 गुना भारी हो जाता है।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Up to ~3 to 4 million years</span><span class=\"t\" lang=\"hi\">लगभग 30 से 40 लाख साल तक</span></div><p><span class=\"t\" lang=\"en\">It pulls in gas fast; meteorites show it split the young disk into an inner and an outer part.</span><span class=\"t\" lang=\"hi\">यह तेज़ी से गैस खींचता है; उल्कापिंड बताते हैं कि इसने नई disk को भीतरी और बाहरी हिस्से में बाँट दिया।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Within ~10 million years</span><span class=\"t\" lang=\"hi\">लगभग 1 करोड़ साल के अंदर</span></div><p><span class=\"t\" lang=\"en\">The gas disk is gone; Jupiter has its full size, and its big moons form around it.</span><span class=\"t\" lang=\"hi\">गैस की disk ख़त्म हो जाती है; बृहस्पति पूरे आकार का हो जाता है और उसके बड़े चाँद बनते हैं।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Today</span><span class=\"t\" lang=\"hi\">आज</span></div><p><span class=\"t\" lang=\"en\">Juno found its core is not a small solid ball but &amp;quot;fuzzy&amp;quot;, spread out and mixed with gas.</span><span class=\"t\" lang=\"hi\">Juno ने पाया कि इसका core कोई छोटी ठोस गेंद नहीं, बल्कि &amp;quot;धुंधला&amp;quot; है, फैला हुआ और गैस से मिला हुआ।</span></p></div></div><div class=\"callout\">❓ <b><span class=\"t\" lang=\"en\">Still unknown</span><span class=\"t\" lang=\"hi\">अभी भी अनजाना</span>:</b> <span class=\"t\" lang=\"en\">Did Jupiter move inward toward the Sun and back out again early on (the &amp;quot;Grand Tack&amp;quot; idea)? It could explain why Mars is small, but it is not proven.</span><span class=\"t\" lang=\"hi\">क्या शुरुआत में बृहस्पति सूरज की ओर अंदर आया और फिर वापस बाहर गया (&amp;quot;Grand Tack&amp;quot; विचार)? इससे पता चल सकता है कि मंगल छोटा क्यों है, पर यह साबित नहीं है।</span></div><p class=\"note\"><span class=\"t\" lang=\"en\">All dates are estimates from meteorites, moon rocks, space missions and computer models.</span><span class=\"t\" lang=\"hi\">सभी तारीख़ें अनुमान हैं, जो उल्कापिंडों, चाँद की चट्टानों, अंतरिक्ष missions और computer models से आती हैं।</span></p><h3><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Did you know?</span><span class=\"t\" lang=\"hi\">क्या आप जानते हैं?</span><span class=\"t\" lang=\"es\">¿Sabías que…?</span><span class=\"t\" lang=\"pt\">Você sabia?</span><span class=\"t\" lang=\"fr\">Le saviez-vous ?</span><span class=\"t\" lang=\"ar\">هل تعلم؟</span></h3><ul class=\"sheetfacts\"><li><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Jupiter has more than twice the mass of all the other planets put together.</span><span class=\"t\" lang=\"hi\">बृहस्पति का द्रव्यमान बाकी सभी ग्रहों के कुल द्रव्यमान से दोगुने से भी ज़्यादा है।</span><span class=\"t\" lang=\"es\">Júpiter tiene más del doble de la masa de todos los demás planetas juntos.</span><span class=\"t\" lang=\"pt\">Júpiter tem mais que o dobro da massa de todos os outros planetas juntos.</span><span class=\"t\" lang=\"fr\">Jupiter a plus de deux fois la masse de toutes les autres planètes réunies.</span><span class=\"t\" lang=\"ar\">كتلة المشتري أكثر من ضعف كتلة كل الكواكب الأخرى مجتمعة.</span></li><li><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">The Great Red Spot is a storm bigger than Earth, and people have watched it for more than 150 years.</span><span class=\"t\" lang=\"hi\">ग्रेट रेड स्पॉट पृथ्वी से बड़ा एक तूफ़ान है, जिसे लोग 150 साल से भी ज़्यादा समय से देख रहे हैं।</span><span class=\"t\" lang=\"es\">La Gran Mancha Roja es una tormenta más grande que la Tierra, y la gente la observa desde hace más de 150 años.</span><span class=\"t\" lang=\"pt\">A Grande Mancha Vermelha é uma tempestade maior que a Terra, e as pessoas a observam há mais de 150 anos.</span><span class=\"t\" lang=\"fr\">La Grande Tache rouge est une tempête plus grande que la Terre, observée depuis plus de 150 ans.</span><span class=\"t\" lang=\"ar\">البقعة الحمراء العظيمة عاصفة أكبر من الأرض، ويراقبها الناس منذ أكثر من 150 عامًا.</span></li></ul><h3><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Major moons</span><span class=\"t\" lang=\"hi\">मुख्य चंद्रमा</span><span class=\"t\" lang=\"es\">Lunas principales</span><span class=\"t\" lang=\"pt\">Luas principais</span><span class=\"t\" lang=\"fr\">Lunes principales</span><span class=\"t\" lang=\"ar\">الأقمار الرئيسية</span></h3><div class=\"sheetmoons\"><a href=\"body/io.html\"><img class=\"pimg\" src=\"img/planets/io-s.webp\" alt=\"Io\" width=\"160\" height=\"160\" loading=\"lazy\" decoding=\"async\"><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Io</span><span class=\"t\" lang=\"hi\">आयो</span><span class=\"t\" lang=\"es\">Ío</span><span class=\"t\" lang=\"pt\">Io</span><span class=\"t\" lang=\"fr\">Io</span><span class=\"t\" lang=\"ar\">آيو</span></span></a><a href=\"body/europa.html\"><img class=\"pimg\" src=\"img/planets/europa-s.webp\" alt=\"Europa\" width=\"160\" height=\"160\" loading=\"lazy\" decoding=\"async\"><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Europa</span><span class=\"t\" lang=\"hi\">यूरोपा</span><span class=\"t\" lang=\"es\">Europa</span><span class=\"t\" lang=\"pt\">Europa</span><span class=\"t\" lang=\"fr\">Europe</span><span class=\"t\" lang=\"ar\">أوروبا</span></span></a><a href=\"body/ganymede.html\"><img class=\"pimg\" src=\"img/planets/ganymede-s.webp\" alt=\"Ganymede\" width=\"160\" height=\"160\" loading=\"lazy\" decoding=\"async\"><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Ganymede</span><span class=\"t\" lang=\"hi\">गैनिमीड</span><span class=\"t\" lang=\"es\">Ganímedes</span><span class=\"t\" lang=\"pt\">Ganimedes</span><span class=\"t\" lang=\"fr\">Ganymède</span><span class=\"t\" lang=\"ar\">غانيميد</span></span></a><a href=\"body/callisto.html\"><img class=\"pimg\" src=\"img/planets/callisto-s.webp\" alt=\"Callisto\" width=\"160\" height=\"160\" loading=\"lazy\" decoding=\"async\"><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Callisto</span><span class=\"t\" lang=\"hi\">कैलिस्टो</span><span class=\"t\" lang=\"es\">Calisto</span><span class=\"t\" lang=\"pt\">Calisto</span><span class=\"t\" lang=\"fr\">Callisto</span><span class=\"t\" lang=\"ar\">كاليستو</span></span></a></div><p><a class=\"btn primary\" href=\"body/jupiter.html\" data-full><span class=\"t\" lang=\"en\">Full page: layers, telescope view, atmosphere</span><span class=\"t\" lang=\"hi\">पूरा page: परतें, दूरबीन का दृश्य, वायुमंडल</span> →</a></p>"},"saturn":{"head":"<div class=\"sheethead\"><img class=\"pimg\" src=\"img/planets/saturn.webp\" alt=\"Saturn\" width=\"600\" height=\"600\" loading=\"eager\" decoding=\"async\"><div><h2 id=\"sheetTitle\"><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Saturn</span><span class=\"t\" lang=\"hi\">शनि</span><span class=\"t\" lang=\"es\">Saturno</span><span class=\"t\" lang=\"pt\">Saturno</span><span class=\"t\" lang=\"fr\">Saturne</span><span class=\"t\" lang=\"ar\">زحل</span></h2><p class=\"sub\"><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Planet 6 from the Sun</span><span class=\"t\" lang=\"hi\">सूर्य से ग्रह क्रमांक 6</span><span class=\"t\" lang=\"es\">Planeta 6 desde el Sol</span><span class=\"t\" lang=\"pt\">Planeta 6 a partir do Sol</span><span class=\"t\" lang=\"fr\">Planète 6 à partir du Soleil</span><span class=\"t\" lang=\"ar\">الكوكب 6 من الشمس</span></p></div></div>","body":"<div class=\"stats\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">120,536 km</span><span class=\"t\" lang=\"hi\">1,20,536 किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Diameter</span><span class=\"t\" lang=\"hi\">व्यास</span><span class=\"t\" lang=\"es\">Diámetro</span><span class=\"t\" lang=\"pt\">Diâmetro</span><span class=\"t\" lang=\"fr\">Diamètre</span><span class=\"t\" lang=\"ar\">القطر</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">9 m/s² (0.92 g)</span><span class=\"t\" lang=\"hi\">9 m/s² (0.92 g)</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Gravity</span><span class=\"t\" lang=\"hi\">गुरुत्वाकर्षण</span><span class=\"t\" lang=\"es\">Gravedad</span><span class=\"t\" lang=\"pt\">Gravidade</span><span class=\"t\" lang=\"fr\">Gravité</span><span class=\"t\" lang=\"ar\">الجاذبية</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">-140 °C</span><span class=\"t\" lang=\"hi\">-140 °C</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Average temperature</span><span class=\"t\" lang=\"hi\">औसत तापमान</span><span class=\"t\" lang=\"es\">Temperatura media</span><span class=\"t\" lang=\"pt\">Temperatura média</span><span class=\"t\" lang=\"fr\">Température moyenne</span><span class=\"t\" lang=\"ar\">متوسط الحرارة</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">10.7 h</span><span class=\"t\" lang=\"hi\">10.7 घंटे</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Day</span><span class=\"t\" lang=\"hi\">दिन</span><span class=\"t\" lang=\"es\">Día</span><span class=\"t\" lang=\"pt\">Dia</span><span class=\"t\" lang=\"fr\">Jour</span><span class=\"t\" lang=\"ar\">اليوم</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">29.4 years</span><span class=\"t\" lang=\"hi\">29.4 वर्ष</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Year</span><span class=\"t\" lang=\"hi\">वर्ष</span><span class=\"t\" lang=\"es\">Año</span><span class=\"t\" lang=\"pt\">Ano</span><span class=\"t\" lang=\"fr\">Année</span><span class=\"t\" lang=\"ar\">السنة</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">293</span><span class=\"t\" lang=\"hi\">293</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Known moons</span><span class=\"t\" lang=\"hi\">ज्ञात चंद्रमा</span><span class=\"t\" lang=\"es\">Lunas conocidas</span><span class=\"t\" lang=\"pt\">Luas conhecidas</span><span class=\"t\" lang=\"fr\">Lunes connues</span><span class=\"t\" lang=\"ar\">الأقمار المعروفة</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">1,432 million km</span><span class=\"t\" lang=\"hi\">1,432 मिलियन किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Distance from the Sun</span><span class=\"t\" lang=\"hi\">सूर्य से दूरी</span><span class=\"t\" lang=\"es\">Distancia al Sol</span><span class=\"t\" lang=\"pt\">Distância do Sol</span><span class=\"t\" lang=\"fr\">Distance du Soleil</span><span class=\"t\" lang=\"ar\">البعد عن الشمس</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">No solid surface</span><span class=\"t\" lang=\"hi\">कोई ठोस सतह नहीं</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Surface pressure</span><span class=\"t\" lang=\"hi\">सतह का दबाव</span><span class=\"t\" lang=\"es\">Presión en la superficie</span><span class=\"t\" lang=\"pt\">Pressão na superfície</span><span class=\"t\" lang=\"fr\">Pression à la surface</span><span class=\"t\" lang=\"ar\">الضغط على السطح</span></span></div></div><h3><span class=\"t\" lang=\"en\">When and how it formed</span><span class=\"t\" lang=\"hi\">कब और कैसे बना</span></h3><div class=\"formhead\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">About 4.6 billion years ago</span><span class=\"t\" lang=\"hi\">लगभग 4.6 अरब साल पहले</span></b><span><span class=\"t\" lang=\"en\">Formed</span><span class=\"t\" lang=\"hi\">कब बना</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">A few million years, soon after Jupiter</span><span class=\"t\" lang=\"hi\">कुछ लाख साल, बृहस्पति के कुछ ही बाद</span></b><span><span class=\"t\" lang=\"en\">How long it took</span><span class=\"t\" lang=\"hi\">कितना समय लगा</span></span></div></div><p><span class=\"t\" lang=\"en\">Saturn formed like Jupiter: an icy core first, then a thick blanket of hydrogen and helium. It grew a little later and caught less gas before the disk faded. Its famous rings came much later.</span><span class=\"t\" lang=\"hi\">शनि बृहस्पति की तरह बना: पहले बर्फ़ीला core, फिर hydrogen और helium की मोटी परत। यह थोड़ा बाद में बना और disk ख़त्म होने से पहले कम गैस पकड़ पाया। उसके मशहूर छल्ले बहुत बाद में आए।</span></p><div class=\"tl formtl\"><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">First few million years</span><span class=\"t\" lang=\"hi\">पहले कुछ लाख साल</span></div><p><span class=\"t\" lang=\"en\">An ice-and-rock core grows beyond Jupiter&amp;#x27;s orbit.</span><span class=\"t\" lang=\"hi\">बृहस्पति की कक्षा के आगे बर्फ़ और चट्टान का core बढ़ता है।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Before ~10 million years</span><span class=\"t\" lang=\"hi\">लगभग 1 करोड़ साल से पहले</span></div><p><span class=\"t\" lang=\"en\">It pulls in gas until the disk around the Sun runs out.</span><span class=\"t\" lang=\"hi\">सूरज के चारों ओर की disk ख़त्म होने तक यह गैस खींचता है।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Soon after</span><span class=\"t\" lang=\"hi\">उसके तुरंत बाद</span></div><p><span class=\"t\" lang=\"en\">Titan and the other moons form in a disk around Saturn.</span><span class=\"t\" lang=\"hi\">Titan और बाकी चाँद शनि के चारों ओर की disk में बनते हैं।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Perhaps a few hundred million years ago</span><span class=\"t\" lang=\"hi\">शायद कुछ करोड़ साल पहले</span></div><p><span class=\"t\" lang=\"en\">Cassini&amp;#x27;s measurements suggest the rings may be only a few hundred million years old or less, but scientists still debate it.</span><span class=\"t\" lang=\"hi\">Cassini के माप बताते हैं कि छल्ले शायद बस कुछ करोड़ साल या उससे भी कम पुराने हैं, पर वैज्ञानिक अभी भी बहस करते हैं।</span></p></div></div><div class=\"callout\">❓ <b><span class=\"t\" lang=\"en\">Still unknown</span><span class=\"t\" lang=\"hi\">अभी भी अनजाना</span>:</b> <span class=\"t\" lang=\"en\">Are the rings young, from a moon or comet torn apart, or as old as Saturn itself and just kept clean? Both ideas still have supporters.</span><span class=\"t\" lang=\"hi\">क्या छल्ले नए हैं, किसी टूटे चाँद या धूमकेतु से, या शनि जितने ही पुराने और बस साफ़ बने रहे? दोनों विचारों के समर्थक हैं।</span></div><p class=\"note\"><span class=\"t\" lang=\"en\">All dates are estimates from meteorites, moon rocks, space missions and computer models.</span><span class=\"t\" lang=\"hi\">सभी तारीख़ें अनुमान हैं, जो उल्कापिंडों, चाँद की चट्टानों, अंतरिक्ष missions और computer models से आती हैं।</span></p><h3><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Did you know?</span><span class=\"t\" lang=\"hi\">क्या आप जानते हैं?</span><span class=\"t\" lang=\"es\">¿Sabías que…?</span><span class=\"t\" lang=\"pt\">Você sabia?</span><span class=\"t\" lang=\"fr\">Le saviez-vous ?</span><span class=\"t\" lang=\"ar\">هل تعلم؟</span></h3><ul class=\"sheetfacts\"><li><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Saturn is so light for its size that it would float in water, if you could find a bathtub big enough.</span><span class=\"t\" lang=\"hi\">शनि अपने आकार के हिसाब से इतना हल्का है कि पानी में तैर जाएगा, अगर इतना बड़ा टब मिल जाए।</span><span class=\"t\" lang=\"es\">Saturno es tan ligero para su tamaño que flotaría en el agua, si encontraras una bañera lo bastante grande.</span><span class=\"t\" lang=\"pt\">Saturno é tão leve para o seu tamanho que boiaria na água, se você achasse uma banheira grande o bastante.</span><span class=\"t\" lang=\"fr\">Saturne est si légère pour sa taille qu&#x27;elle flotterait sur l&#x27;eau, si l&#x27;on trouvait une baignoire assez grande.</span><span class=\"t\" lang=\"ar\">زحل خفيف بالنسبة لحجمه حتى إنه سيطفو على الماء لو وجدت حوض استحمام يكفي.</span></li><li><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Saturn&#x27;s rings are very wide but very thin: in places only about ten metres thick.</span><span class=\"t\" lang=\"hi\">शनि के छल्ले बहुत चौड़े पर बहुत पतले हैं: कई जगह सिर्फ़ करीब दस मीटर मोटे।</span><span class=\"t\" lang=\"es\">Los anillos de Saturno son muy anchos pero muy delgados: en algunos puntos tienen solo unos diez metros de grosor.</span><span class=\"t\" lang=\"pt\">Os anéis de Saturno são muito largos, mas muito finos: em alguns pontos têm só cerca de dez metros de espessura.</span><span class=\"t\" lang=\"fr\">Les anneaux de Saturne sont très larges mais très fins : par endroits, seulement une dizaine de mètres d&#x27;épaisseur.</span><span class=\"t\" lang=\"ar\">حلقات زحل عريضة جدًا لكنها رقيقة جدًا: في بعض المواضع لا يزيد سمكها على نحو عشرة أمتار.</span></li></ul><h3><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Major moons</span><span class=\"t\" lang=\"hi\">मुख्य चंद्रमा</span><span class=\"t\" lang=\"es\">Lunas principales</span><span class=\"t\" lang=\"pt\">Luas principais</span><span class=\"t\" lang=\"fr\">Lunes principales</span><span class=\"t\" lang=\"ar\">الأقمار الرئيسية</span></h3><div class=\"sheetmoons\"><a href=\"body/titan.html\"><img class=\"pimg\" src=\"img/planets/titan-s.webp\" alt=\"Titan\" width=\"160\" height=\"160\" loading=\"lazy\" decoding=\"async\"><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Titan</span><span class=\"t\" lang=\"hi\">टाइटन</span><span class=\"t\" lang=\"es\">Titán</span><span class=\"t\" lang=\"pt\">Titã</span><span class=\"t\" lang=\"fr\">Titan</span><span class=\"t\" lang=\"ar\">تيتان</span></span></a><a href=\"body/enceladus.html\"><img class=\"pimg\" src=\"img/planets/enceladus-s.webp\" alt=\"Enceladus\" width=\"160\" height=\"160\" loading=\"lazy\" decoding=\"async\"><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Enceladus</span><span class=\"t\" lang=\"hi\">एन्सेलेडस</span><span class=\"t\" lang=\"es\">Encélado</span><span class=\"t\" lang=\"pt\">Encélado</span><span class=\"t\" lang=\"fr\">Encelade</span><span class=\"t\" lang=\"ar\">إنسيلادوس</span></span></a></div><p><a class=\"btn primary\" href=\"body/saturn.html\" data-full><span class=\"t\" lang=\"en\">Full page: layers, telescope view, atmosphere</span><span class=\"t\" lang=\"hi\">पूरा page: परतें, दूरबीन का दृश्य, वायुमंडल</span> →</a></p>"},"uranus":{"head":"<div class=\"sheethead\"><img class=\"pimg\" src=\"img/planets/uranus.webp\" alt=\"Uranus\" width=\"600\" height=\"600\" loading=\"eager\" decoding=\"async\"><div><h2 id=\"sheetTitle\"><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Uranus</span><span class=\"t\" lang=\"hi\">अरुण</span><span class=\"t\" lang=\"es\">Urano</span><span class=\"t\" lang=\"pt\">Urano</span><span class=\"t\" lang=\"fr\">Uranus</span><span class=\"t\" lang=\"ar\">أورانوس</span></h2><p class=\"sub\"><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Planet 7 from the Sun</span><span class=\"t\" lang=\"hi\">सूर्य से ग्रह क्रमांक 7</span><span class=\"t\" lang=\"es\">Planeta 7 desde el Sol</span><span class=\"t\" lang=\"pt\">Planeta 7 a partir do Sol</span><span class=\"t\" lang=\"fr\">Planète 7 à partir du Soleil</span><span class=\"t\" lang=\"ar\">الكوكب 7 من الشمس</span></p></div></div>","body":"<div class=\"stats\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">51,118 km</span><span class=\"t\" lang=\"hi\">51,118 किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Diameter</span><span class=\"t\" lang=\"hi\">व्यास</span><span class=\"t\" lang=\"es\">Diámetro</span><span class=\"t\" lang=\"pt\">Diâmetro</span><span class=\"t\" lang=\"fr\">Diamètre</span><span class=\"t\" lang=\"ar\">القطر</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">8.7 m/s² (0.89 g)</span><span class=\"t\" lang=\"hi\">8.7 m/s² (0.89 g)</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Gravity</span><span class=\"t\" lang=\"hi\">गुरुत्वाकर्षण</span><span class=\"t\" lang=\"es\">Gravedad</span><span class=\"t\" lang=\"pt\">Gravidade</span><span class=\"t\" lang=\"fr\">Gravité</span><span class=\"t\" lang=\"ar\">الجاذبية</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">-195 °C</span><span class=\"t\" lang=\"hi\">-195 °C</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Average temperature</span><span class=\"t\" lang=\"hi\">औसत तापमान</span><span class=\"t\" lang=\"es\">Temperatura media</span><span class=\"t\" lang=\"pt\">Temperatura média</span><span class=\"t\" lang=\"fr\">Température moyenne</span><span class=\"t\" lang=\"ar\">متوسط الحرارة</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">17.2 h</span><span class=\"t\" lang=\"hi\">17.2 घंटे</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Day</span><span class=\"t\" lang=\"hi\">दिन</span><span class=\"t\" lang=\"es\">Día</span><span class=\"t\" lang=\"pt\">Dia</span><span class=\"t\" lang=\"fr\">Jour</span><span class=\"t\" lang=\"ar\">اليوم</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">83.7 years</span><span class=\"t\" lang=\"hi\">83.7 वर्ष</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Year</span><span class=\"t\" lang=\"hi\">वर्ष</span><span class=\"t\" lang=\"es\">Año</span><span class=\"t\" lang=\"pt\">Ano</span><span class=\"t\" lang=\"fr\">Année</span><span class=\"t\" lang=\"ar\">السنة</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">29</span><span class=\"t\" lang=\"hi\">29</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Known moons</span><span class=\"t\" lang=\"hi\">ज्ञात चंद्रमा</span><span class=\"t\" lang=\"es\">Lunas conocidas</span><span class=\"t\" lang=\"pt\">Luas conhecidas</span><span class=\"t\" lang=\"fr\">Lunes connues</span><span class=\"t\" lang=\"ar\">الأقمار المعروفة</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">2,867 million km</span><span class=\"t\" lang=\"hi\">2,867 मिलियन किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Distance from the Sun</span><span class=\"t\" lang=\"hi\">सूर्य से दूरी</span><span class=\"t\" lang=\"es\">Distancia al Sol</span><span class=\"t\" lang=\"pt\">Distância do Sol</span><span class=\"t\" lang=\"fr\">Distance du Soleil</span><span class=\"t\" lang=\"ar\">البعد عن الشمس</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">No solid surface</span><span class=\"t\" lang=\"hi\">कोई ठोस सतह नहीं</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Surface pressure</span><span class=\"t\" lang=\"hi\">सतह का दबाव</span><span class=\"t\" lang=\"es\">Presión en la superficie</span><span class=\"t\" lang=\"pt\">Pressão na superfície</span><span class=\"t\" lang=\"fr\">Pression à la surface</span><span class=\"t\" lang=\"ar\">الضغط على السطح</span></span></div></div><h3><span class=\"t\" lang=\"en\">When and how it formed</span><span class=\"t\" lang=\"hi\">कब और कैसे बना</span></h3><div class=\"formhead\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">About 4.6 billion years ago</span><span class=\"t\" lang=\"hi\">लगभग 4.6 अरब साल पहले</span></b><span><span class=\"t\" lang=\"en\">Formed</span><span class=\"t\" lang=\"hi\">कब बना</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">Longer than Jupiter and Saturn, perhaps several million years</span><span class=\"t\" lang=\"hi\">बृहस्पति और शनि से ज़्यादा, शायद कई लाख साल</span></b><span><span class=\"t\" lang=\"en\">How long it took</span><span class=\"t\" lang=\"hi\">कितना समय लगा</span></span></div></div><p><span class=\"t\" lang=\"en\">Uranus grew a large core of ice and rock, but the gas disk was fading by then, so it caught only a thin layer of hydrogen and helium. That is why it is an &amp;quot;ice giant&amp;quot;. It probably formed closer to the Sun and moved outward later. Something big knocked it onto its side.</span><span class=\"t\" lang=\"hi\">यूरेनस ने बर्फ़ और चट्टान का बड़ा core बनाया, पर तब तक गैस की disk ख़त्म हो रही थी, इसलिए उसे hydrogen और helium की पतली परत ही मिली। इसीलिए यह &amp;quot;ice giant&amp;quot; है। शायद यह सूरज के ज़्यादा पास बना और बाद में बाहर चला गया। किसी बड़ी चीज़ ने इसे करवट लिटा दिया।</span></p><div class=\"tl formtl\"><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">First few million years</span><span class=\"t\" lang=\"hi\">पहले कुछ लाख साल</span></div><p><span class=\"t\" lang=\"en\">An ice-rich core grows, probably closer to the Sun than today.</span><span class=\"t\" lang=\"hi\">बर्फ़ से भरा core बढ़ता है, शायद आज से ज़्यादा सूरज के पास।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">As the gas fades</span><span class=\"t\" lang=\"hi\">जब गैस ख़त्म हो रही थी</span></div><p><span class=\"t\" lang=\"en\">It gathers only a thin hydrogen-helium envelope.</span><span class=\"t\" lang=\"hi\">इसे hydrogen-helium की बस पतली परत मिलती है।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Early on</span><span class=\"t\" lang=\"hi\">शुरुआत में</span></div><p><span class=\"t\" lang=\"en\">One or more giant impacts tilt it to about 98 degrees, rolling it around the Sun on its side.</span><span class=\"t\" lang=\"hi\">एक या ज़्यादा बड़ी टक्करें इसे लगभग 98 डिग्री झुका देती हैं, यह करवट लेकर सूरज का चक्कर लगाता है।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">First few hundred million years</span><span class=\"t\" lang=\"hi\">पहले कुछ करोड़ साल</span></div><p><span class=\"t\" lang=\"en\">The giant planets shuffle their orbits and Uranus settles farther out.</span><span class=\"t\" lang=\"hi\">विशाल ग्रह अपनी कक्षाएँ बदलते हैं और यूरेनस और दूर जाकर बस जाता है।</span></p></div></div><div class=\"callout\">❓ <b><span class=\"t\" lang=\"en\">Still unknown</span><span class=\"t\" lang=\"hi\">अभी भी अनजाना</span>:</b> <span class=\"t\" lang=\"en\">Exactly what tipped Uranus over, and why it gives off so little inner heat, is still unknown. Only Voyager 2 has visited, in 1986.</span><span class=\"t\" lang=\"hi\">यूरेनस को किसने पलटा, और यह अंदर से इतनी कम गर्मी क्यों छोड़ता है, यह अभी तक पता नहीं है। सिर्फ़ Voyager 2 वहाँ गया है, 1986 में।</span></div><p class=\"note\"><span class=\"t\" lang=\"en\">All dates are estimates from meteorites, moon rocks, space missions and computer models.</span><span class=\"t\" lang=\"hi\">सभी तारीख़ें अनुमान हैं, जो उल्कापिंडों, चाँद की चट्टानों, अंतरिक्ष missions और computer models से आती हैं।</span></p><h3><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Did you know?</span><span class=\"t\" lang=\"hi\">क्या आप जानते हैं?</span><span class=\"t\" lang=\"es\">¿Sabías que…?</span><span class=\"t\" lang=\"pt\">Você sabia?</span><span class=\"t\" lang=\"fr\">Le saviez-vous ?</span><span class=\"t\" lang=\"ar\">هل تعلم؟</span></h3><ul class=\"sheetfacts\"><li><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Uranus rolls around the Sun on its side, tilted by about 98 degrees.</span><span class=\"t\" lang=\"hi\">अरुण अपनी बगल के बल लुढ़कते हुए सूर्य का चक्कर लगाता है, उसकी धुरी करीब 98 डिग्री झुकी है।</span><span class=\"t\" lang=\"es\">Urano rueda alrededor del Sol de lado, inclinado unos 98 grados.</span><span class=\"t\" lang=\"pt\">Urano rola em volta do Sol de lado, inclinado cerca de 98 graus.</span><span class=\"t\" lang=\"fr\">Uranus roule autour du Soleil sur le côté, inclinée d&#x27;environ 98 degrés.</span><span class=\"t\" lang=\"ar\">يدور أورانوس حول الشمس مستلقيًا على جانبه، بميل نحو 98 درجة.</span></li><li><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Uranus was the first planet found with a telescope. William Herschel spotted it in 1781.</span><span class=\"t\" lang=\"hi\">अरुण दूरबीन से खोजा गया पहला ग्रह था। विलियम हर्शल ने उसे 1781 में देखा।</span><span class=\"t\" lang=\"es\">Urano fue el primer planeta descubierto con un telescopio. William Herschel lo vio en 1781.</span><span class=\"t\" lang=\"pt\">Urano foi o primeiro planeta achado com telescópio. William Herschel o viu em 1781.</span><span class=\"t\" lang=\"fr\">Uranus a été la première planète découverte au télescope. William Herschel l&#x27;a repérée en 1781.</span><span class=\"t\" lang=\"ar\">أورانوس أول كوكب اكتُشف بالتلسكوب. رصده ويليام هيرشل عام 1781.</span></li></ul><p><a class=\"btn primary\" href=\"body/uranus.html\" data-full><span class=\"t\" lang=\"en\">Full page: layers, telescope view, atmosphere</span><span class=\"t\" lang=\"hi\">पूरा page: परतें, दूरबीन का दृश्य, वायुमंडल</span> →</a></p>"},"neptune":{"head":"<div class=\"sheethead\"><img class=\"pimg\" src=\"img/planets/neptune.webp\" alt=\"Neptune\" width=\"600\" height=\"600\" loading=\"eager\" decoding=\"async\"><div><h2 id=\"sheetTitle\"><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Neptune</span><span class=\"t\" lang=\"hi\">वरुण</span><span class=\"t\" lang=\"es\">Neptuno</span><span class=\"t\" lang=\"pt\">Netuno</span><span class=\"t\" lang=\"fr\">Neptune</span><span class=\"t\" lang=\"ar\">نبتون</span></h2><p class=\"sub\"><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Planet 8 from the Sun</span><span class=\"t\" lang=\"hi\">सूर्य से ग्रह क्रमांक 8</span><span class=\"t\" lang=\"es\">Planeta 8 desde el Sol</span><span class=\"t\" lang=\"pt\">Planeta 8 a partir do Sol</span><span class=\"t\" lang=\"fr\">Planète 8 à partir du Soleil</span><span class=\"t\" lang=\"ar\">الكوكب 8 من الشمس</span></p></div></div>","body":"<div class=\"stats\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">49,528 km</span><span class=\"t\" lang=\"hi\">49,528 किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Diameter</span><span class=\"t\" lang=\"hi\">व्यास</span><span class=\"t\" lang=\"es\">Diámetro</span><span class=\"t\" lang=\"pt\">Diâmetro</span><span class=\"t\" lang=\"fr\">Diamètre</span><span class=\"t\" lang=\"ar\">القطر</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">11 m/s² (1.12 g)</span><span class=\"t\" lang=\"hi\">11 m/s² (1.12 g)</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Gravity</span><span class=\"t\" lang=\"hi\">गुरुत्वाकर्षण</span><span class=\"t\" lang=\"es\">Gravedad</span><span class=\"t\" lang=\"pt\">Gravidade</span><span class=\"t\" lang=\"fr\">Gravité</span><span class=\"t\" lang=\"ar\">الجاذبية</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">-200 °C</span><span class=\"t\" lang=\"hi\">-200 °C</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Average temperature</span><span class=\"t\" lang=\"hi\">औसत तापमान</span><span class=\"t\" lang=\"es\">Temperatura media</span><span class=\"t\" lang=\"pt\">Temperatura média</span><span class=\"t\" lang=\"fr\">Température moyenne</span><span class=\"t\" lang=\"ar\">متوسط الحرارة</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">16.1 h</span><span class=\"t\" lang=\"hi\">16.1 घंटे</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Day</span><span class=\"t\" lang=\"hi\">दिन</span><span class=\"t\" lang=\"es\">Día</span><span class=\"t\" lang=\"pt\">Dia</span><span class=\"t\" lang=\"fr\">Jour</span><span class=\"t\" lang=\"ar\">اليوم</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">163.7 years</span><span class=\"t\" lang=\"hi\">163.7 वर्ष</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Year</span><span class=\"t\" lang=\"hi\">वर्ष</span><span class=\"t\" lang=\"es\">Año</span><span class=\"t\" lang=\"pt\">Ano</span><span class=\"t\" lang=\"fr\">Année</span><span class=\"t\" lang=\"ar\">السنة</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">16</span><span class=\"t\" lang=\"hi\">16</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Known moons</span><span class=\"t\" lang=\"hi\">ज्ञात चंद्रमा</span><span class=\"t\" lang=\"es\">Lunas conocidas</span><span class=\"t\" lang=\"pt\">Luas conhecidas</span><span class=\"t\" lang=\"fr\">Lunes connues</span><span class=\"t\" lang=\"ar\">الأقمار المعروفة</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">4,515 million km</span><span class=\"t\" lang=\"hi\">4,515 मिलियन किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Distance from the Sun</span><span class=\"t\" lang=\"hi\">सूर्य से दूरी</span><span class=\"t\" lang=\"es\">Distancia al Sol</span><span class=\"t\" lang=\"pt\">Distância do Sol</span><span class=\"t\" lang=\"fr\">Distance du Soleil</span><span class=\"t\" lang=\"ar\">البعد عن الشمس</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">No solid surface</span><span class=\"t\" lang=\"hi\">कोई ठोस सतह नहीं</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Surface pressure</span><span class=\"t\" lang=\"hi\">सतह का दबाव</span><span class=\"t\" lang=\"es\">Presión en la superficie</span><span class=\"t\" lang=\"pt\">Pressão na superfície</span><span class=\"t\" lang=\"fr\">Pression à la surface</span><span class=\"t\" lang=\"ar\">الضغط على السطح</span></span></div></div><h3><span class=\"t\" lang=\"en\">When and how it formed</span><span class=\"t\" lang=\"hi\">कब और कैसे बना</span></h3><div class=\"formhead\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">About 4.6 billion years ago</span><span class=\"t\" lang=\"hi\">लगभग 4.6 अरब साल पहले</span></b><span><span class=\"t\" lang=\"en\">Formed</span><span class=\"t\" lang=\"hi\">कब बना</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">Several million years, like Uranus</span><span class=\"t\" lang=\"hi\">कई लाख साल, यूरेनस की तरह</span></b><span><span class=\"t\" lang=\"en\">How long it took</span><span class=\"t\" lang=\"hi\">कितना समय लगा</span></span></div></div><p><span class=\"t\" lang=\"en\">Neptune is Uranus&amp;#x27;s twin: a big ice-and-rock core with a thinner gas layer. It most likely formed closer to the Sun and was pushed outward, scattering icy bodies and shaping the Kuiper Belt beyond it.</span><span class=\"t\" lang=\"hi\">नेपच्यून यूरेनस का जुड़वाँ है: बर्फ़ और चट्टान का बड़ा core, गैस की पतली परत के साथ। सबसे संभावना है कि यह सूरज के ज़्यादा पास बना और बाहर धकेला गया, जिससे बर्फ़ीले पिंड बिखरे और उसके आगे Kuiper Belt बना।</span></p><div class=\"tl formtl\"><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">First few million years</span><span class=\"t\" lang=\"hi\">पहले कुछ लाख साल</span></div><p><span class=\"t\" lang=\"en\">An icy core grows and collects a thin envelope of gas.</span><span class=\"t\" lang=\"hi\">बर्फ़ीला core बढ़ता है और गैस की पतली परत जमा करता है।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">First few hundred million years</span><span class=\"t\" lang=\"hi\">पहले कुछ करोड़ साल</span></div><p><span class=\"t\" lang=\"en\">It migrates outward, scattering icy bodies; some are flung toward the inner planets.</span><span class=\"t\" lang=\"hi\">यह बाहर की ओर खिसकता है, बर्फ़ीले पिंडों को बिखेरता है; कुछ भीतरी ग्रहों की ओर फेंके जाते हैं।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">During the move</span><span class=\"t\" lang=\"hi\">इस सफ़र में</span></div><p><span class=\"t\" lang=\"en\">It pushes Pluto and other bodies into step with its own orbit (2 Pluto years for every 3 Neptune years).</span><span class=\"t\" lang=\"hi\">यह प्लूटो और दूसरे पिंडों को अपनी कक्षा की लय में ले आता है (नेपच्यून के हर 3 साल में प्लूटो के 2 साल)।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Later</span><span class=\"t\" lang=\"hi\">बाद में</span></div><p><span class=\"t\" lang=\"en\">It captures Triton, a dwarf planet from the Kuiper Belt.</span><span class=\"t\" lang=\"hi\">यह Kuiper Belt के एक बौने ग्रह, Triton, को पकड़ लेता है।</span></p></div></div><div class=\"callout\">❓ <b><span class=\"t\" lang=\"en\">Still unknown</span><span class=\"t\" lang=\"hi\">अभी भी अनजाना</span>:</b> <span class=\"t\" lang=\"en\">The exact path of the giant planets&amp;#x27; move (the &amp;quot;Nice model&amp;quot;) is still being worked out.</span><span class=\"t\" lang=\"hi\">विशाल ग्रहों के खिसकने का सही रास्ता (&amp;quot;Nice model&amp;quot;) अभी भी समझा जा रहा है।</span></div><p class=\"note\"><span class=\"t\" lang=\"en\">All dates are estimates from meteorites, moon rocks, space missions and computer models.</span><span class=\"t\" lang=\"hi\">सभी तारीख़ें अनुमान हैं, जो उल्कापिंडों, चाँद की चट्टानों, अंतरिक्ष missions और computer models से आती हैं।</span></p><h3><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Did you know?</span><span class=\"t\" lang=\"hi\">क्या आप जानते हैं?</span><span class=\"t\" lang=\"es\">¿Sabías que…?</span><span class=\"t\" lang=\"pt\">Você sabia?</span><span class=\"t\" lang=\"fr\">Le saviez-vous ?</span><span class=\"t\" lang=\"ar\">هل تعلم؟</span></h3><ul class=\"sheetfacts\"><li><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Neptune has the fastest winds of any planet, more than 2,000 km/h.</span><span class=\"t\" lang=\"hi\">वरुण पर किसी भी ग्रह से तेज़ हवाएँ चलती हैं, 2,000 किमी/घंटा से भी ज़्यादा।</span><span class=\"t\" lang=\"es\">Neptuno tiene los vientos más rápidos de todos los planetas, de más de 2.000 km/h.</span><span class=\"t\" lang=\"pt\">Netuno tem os ventos mais rápidos de todos os planetas, de mais de 2.000 km/h.</span><span class=\"t\" lang=\"fr\">Neptune a les vents les plus rapides de toutes les planètes, plus de 2 000 km/h.</span><span class=\"t\" lang=\"ar\">لنبتون أسرع رياح بين الكواكب، أكثر من 2,000 كم/س.</span></li><li><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Neptune was found with maths before anyone saw it: in 1846 astronomers worked out where it had to be.</span><span class=\"t\" lang=\"hi\">वरुण को किसी के देखने से पहले गणित से खोजा गया: 1846 में खगोलविदों ने हिसाब लगाया कि वह कहाँ होना चाहिए।</span><span class=\"t\" lang=\"es\">Neptuno se encontró con matemáticas antes de que nadie lo viera: en 1846 los astrónomos calcularon dónde tenía que estar.</span><span class=\"t\" lang=\"pt\">Netuno foi achado com matemática antes de alguém vê-lo: em 1846, astrônomos calcularam onde ele tinha de estar.</span><span class=\"t\" lang=\"fr\">Neptune a été trouvée par les maths avant que quiconque la voie : en 1846, des astronomes ont calculé où elle devait être.</span><span class=\"t\" lang=\"ar\">اكتُشف نبتون بالرياضيات قبل أن يراه أحد: ففي عام 1846 حسب الفلكيون موضعه المتوقع.</span></li></ul><h3><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Major moons</span><span class=\"t\" lang=\"hi\">मुख्य चंद्रमा</span><span class=\"t\" lang=\"es\">Lunas principales</span><span class=\"t\" lang=\"pt\">Luas principais</span><span class=\"t\" lang=\"fr\">Lunes principales</span><span class=\"t\" lang=\"ar\">الأقمار الرئيسية</span></h3><div class=\"sheetmoons\"><a href=\"body/triton.html\"><img class=\"pimg\" src=\"img/planets/triton-s.webp\" alt=\"Triton\" width=\"160\" height=\"160\" loading=\"lazy\" decoding=\"async\"><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Triton</span><span class=\"t\" lang=\"hi\">ट्राइटन</span><span class=\"t\" lang=\"es\">Tritón</span><span class=\"t\" lang=\"pt\">Tritão</span><span class=\"t\" lang=\"fr\">Triton</span><span class=\"t\" lang=\"ar\">تريتون</span></span></a></div><p><a class=\"btn primary\" href=\"body/neptune.html\" data-full><span class=\"t\" lang=\"en\">Full page: layers, telescope view, atmosphere</span><span class=\"t\" lang=\"hi\">पूरा page: परतें, दूरबीन का दृश्य, वायुमंडल</span> →</a></p>"},"pluto":{"head":"<div class=\"sheethead\"><img class=\"pimg\" src=\"img/planets/pluto.webp\" alt=\"Pluto\" width=\"600\" height=\"600\" loading=\"eager\" decoding=\"async\"><div><h2 id=\"sheetTitle\"><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Pluto</span><span class=\"t\" lang=\"hi\">प्लूटो</span><span class=\"t\" lang=\"es\">Plutón</span><span class=\"t\" lang=\"pt\">Plutão</span><span class=\"t\" lang=\"fr\">Pluton</span><span class=\"t\" lang=\"ar\">بلوتو</span></h2><p class=\"sub\"><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Dwarf planet</span><span class=\"t\" lang=\"hi\">बौना ग्रह</span><span class=\"t\" lang=\"es\">Planeta enano</span><span class=\"t\" lang=\"pt\">Planeta anão</span><span class=\"t\" lang=\"fr\">Planète naine</span><span class=\"t\" lang=\"ar\">كوكب قزم</span></p></div></div>","body":"<div class=\"stats\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">2,376 km</span><span class=\"t\" lang=\"hi\">2,376 किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Diameter</span><span class=\"t\" lang=\"hi\">व्यास</span><span class=\"t\" lang=\"es\">Diámetro</span><span class=\"t\" lang=\"pt\">Diâmetro</span><span class=\"t\" lang=\"fr\">Diamètre</span><span class=\"t\" lang=\"ar\">القطر</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">0.6 m/s² (0.06 g)</span><span class=\"t\" lang=\"hi\">0.6 m/s² (0.06 g)</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Gravity</span><span class=\"t\" lang=\"hi\">गुरुत्वाकर्षण</span><span class=\"t\" lang=\"es\">Gravedad</span><span class=\"t\" lang=\"pt\">Gravidade</span><span class=\"t\" lang=\"fr\">Gravité</span><span class=\"t\" lang=\"ar\">الجاذبية</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">-225 °C</span><span class=\"t\" lang=\"hi\">-225 °C</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Average temperature</span><span class=\"t\" lang=\"hi\">औसत तापमान</span><span class=\"t\" lang=\"es\">Temperatura media</span><span class=\"t\" lang=\"pt\">Temperatura média</span><span class=\"t\" lang=\"fr\">Température moyenne</span><span class=\"t\" lang=\"ar\">متوسط الحرارة</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">6.4 days</span><span class=\"t\" lang=\"hi\">6.4 दिन</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Day</span><span class=\"t\" lang=\"hi\">दिन</span><span class=\"t\" lang=\"es\">Día</span><span class=\"t\" lang=\"pt\">Dia</span><span class=\"t\" lang=\"fr\">Jour</span><span class=\"t\" lang=\"ar\">اليوم</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">247.9 years</span><span class=\"t\" lang=\"hi\">247.9 वर्ष</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Year</span><span class=\"t\" lang=\"hi\">वर्ष</span><span class=\"t\" lang=\"es\">Año</span><span class=\"t\" lang=\"pt\">Ano</span><span class=\"t\" lang=\"fr\">Année</span><span class=\"t\" lang=\"ar\">السنة</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">5</span><span class=\"t\" lang=\"hi\">5</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Known moons</span><span class=\"t\" lang=\"hi\">ज्ञात चंद्रमा</span><span class=\"t\" lang=\"es\">Lunas conocidas</span><span class=\"t\" lang=\"pt\">Luas conhecidas</span><span class=\"t\" lang=\"fr\">Lunes connues</span><span class=\"t\" lang=\"ar\">الأقمار المعروفة</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">5,906.4 million km</span><span class=\"t\" lang=\"hi\">5,906.4 मिलियन किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Distance from the Sun</span><span class=\"t\" lang=\"hi\">सूर्य से दूरी</span><span class=\"t\" lang=\"es\">Distancia al Sol</span><span class=\"t\" lang=\"pt\">Distância do Sol</span><span class=\"t\" lang=\"fr\">Distance du Soleil</span><span class=\"t\" lang=\"ar\">البعد عن الشمس</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">&lt; 0.001 bar</span><span class=\"t\" lang=\"hi\">&lt; 0.001 bar</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Surface pressure</span><span class=\"t\" lang=\"hi\">सतह का दबाव</span><span class=\"t\" lang=\"es\">Presión en la superficie</span><span class=\"t\" lang=\"pt\">Pressão na superfície</span><span class=\"t\" lang=\"fr\">Pression à la surface</span><span class=\"t\" lang=\"ar\">الضغط على السطح</span></span></div></div><h3><span class=\"t\" lang=\"en\">When and how it formed</span><span class=\"t\" lang=\"hi\">कब और कैसे बना</span></h3><div class=\"formhead\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">About 4.6 billion years ago</span><span class=\"t\" lang=\"hi\">लगभग 4.6 अरब साल पहले</span></b><span><span class=\"t\" lang=\"en\">Formed</span><span class=\"t\" lang=\"hi\">कब बना</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">Unknown; it grew slowly from icy bodies far from the Sun</span><span class=\"t\" lang=\"hi\">पक्का नहीं; सूरज से दूर बर्फ़ीले पिंडों से धीरे-धीरे बना</span></b><span><span class=\"t\" lang=\"en\">How long it took</span><span class=\"t\" lang=\"hi\">कितना समय लगा</span></span></div></div><p><span class=\"t\" lang=\"en\">Pluto formed in the cold outer disk from icy pebbles and small bodies, like many other Kuiper Belt objects. Its big moon Charon was probably made by a slow, glancing collision. Neptune&amp;#x27;s outward move later locked Pluto into its present orbit.</span><span class=\"t\" lang=\"hi\">प्लूटो ठंडी बाहरी disk में बर्फ़ीले कंकड़ों और छोटे पिंडों से बना, Kuiper Belt के बहुत से पिंडों की तरह। उसका बड़ा चाँद Charon शायद एक धीमी, तिरछी टक्कर से बना। बाद में नेपच्यून के बाहर खिसकने ने प्लूटो को उसकी आज की कक्षा में बाँध दिया।</span></p><div class=\"tl formtl\"><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">4.6 billion years ago</span><span class=\"t\" lang=\"hi\">4.6 अरब साल पहले</span></div><p><span class=\"t\" lang=\"en\">Icy pebbles in the far disk gather into small worlds.</span><span class=\"t\" lang=\"hi\">दूर की disk में बर्फ़ीले कंकड़ जुड़कर छोटी दुनियाएँ बनाते हैं।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Early on</span><span class=\"t\" lang=\"hi\">शुरुआत में</span></div><p><span class=\"t\" lang=\"en\">A collision with another body forms Charon and Pluto&amp;#x27;s small moons.</span><span class=\"t\" lang=\"hi\">किसी दूसरे पिंड से टक्कर से Charon और प्लूटो के छोटे चाँद बनते हैं।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">First few hundred million years</span><span class=\"t\" lang=\"hi\">पहले कुछ करोड़ साल</span></div><p><span class=\"t\" lang=\"en\">Neptune moves outward and pushes Pluto into its tilted, stretched orbit.</span><span class=\"t\" lang=\"hi\">नेपच्यून बाहर खिसकता है और प्लूटो को उसकी झुकी, लंबी कक्षा में धकेल देता है।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Recent</span><span class=\"t\" lang=\"hi\">हाल में</span></div><p><span class=\"t\" lang=\"en\">New Horizons (2015) found young ice plains with no craters, so Pluto is still active.</span><span class=\"t\" lang=\"hi\">New Horizons (2015) को बिना गड्ढों के नए बर्फ़ीले मैदान मिले, यानी प्लूटो अभी भी सक्रिय है।</span></p></div></div><div class=\"callout\">❓ <b><span class=\"t\" lang=\"en\">Still unknown</span><span class=\"t\" lang=\"hi\">अभी भी अनजाना</span>:</b> <span class=\"t\" lang=\"en\">What keeps Pluto active so far from the Sun? A hidden ocean under the ice is one possible answer.</span><span class=\"t\" lang=\"hi\">सूरज से इतनी दूर प्लूटो को सक्रिय कौन रखता है? बर्फ़ के नीचे छिपा समुद्र एक संभावित जवाब है।</span></div><p class=\"note\"><span class=\"t\" lang=\"en\">All dates are estimates from meteorites, moon rocks, space missions and computer models.</span><span class=\"t\" lang=\"hi\">सभी तारीख़ें अनुमान हैं, जो उल्कापिंडों, चाँद की चट्टानों, अंतरिक्ष missions और computer models से आती हैं।</span></p><h3><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Did you know?</span><span class=\"t\" lang=\"hi\">क्या आप जानते हैं?</span><span class=\"t\" lang=\"es\">¿Sabías que…?</span><span class=\"t\" lang=\"pt\">Você sabia?</span><span class=\"t\" lang=\"fr\">Le saviez-vous ?</span><span class=\"t\" lang=\"ar\">هل تعلم؟</span></h3><ul class=\"sheetfacts\"><li><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">A year on Pluto lasts about 248 Earth years.</span><span class=\"t\" lang=\"hi\">प्लूटो पर एक साल करीब 248 पृथ्वी-वर्षों का होता है।</span><span class=\"t\" lang=\"es\">Un año en Plutón dura unos 248 años terrestres.</span><span class=\"t\" lang=\"pt\">Um ano em Plutão dura cerca de 248 anos terrestres.</span><span class=\"t\" lang=\"fr\">Une année sur Pluton dure environ 248 années terrestres.</span><span class=\"t\" lang=\"ar\">تستمر السنة على بلوتو نحو 248 سنة أرضية.</span></li><li><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Pluto has a huge heart-shaped plain of frozen nitrogen.</span><span class=\"t\" lang=\"hi\">प्लूटो पर जमी हुई नाइट्रोजन का दिल के आकार का एक विशाल मैदान है।</span><span class=\"t\" lang=\"es\">Plutón tiene una enorme llanura con forma de corazón hecha de nitrógeno helado.</span><span class=\"t\" lang=\"pt\">Plutão tem uma enorme planície em forma de coração feita de nitrogênio congelado.</span><span class=\"t\" lang=\"fr\">Pluton a une immense plaine en forme de cœur faite d&#x27;azote gelé.</span><span class=\"t\" lang=\"ar\">لبلوتو سهل ضخم على شكل قلب من النيتروجين المتجمد.</span></li></ul><p><a class=\"btn primary\" href=\"body/pluto.html\" data-full><span class=\"t\" lang=\"en\">Full page: layers, telescope view, atmosphere</span><span class=\"t\" lang=\"hi\">पूरा page: परतें, दूरबीन का दृश्य, वायुमंडल</span> →</a></p>"},"moon":{"head":"<div class=\"sheethead\"><img class=\"pimg\" src=\"img/planets/moon.webp\" alt=\"Moon\" width=\"600\" height=\"600\" loading=\"eager\" decoding=\"async\"><div><h2 id=\"sheetTitle\"><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Moon</span><span class=\"t\" lang=\"hi\">चंद्रमा</span><span class=\"t\" lang=\"es\">Luna</span><span class=\"t\" lang=\"pt\">Lua</span><span class=\"t\" lang=\"fr\">Lune</span><span class=\"t\" lang=\"ar\">القمر</span></h2><p class=\"sub\"><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Moon of Earth</span><span class=\"t\" lang=\"hi\">पृथ्वी का चंद्रमा</span><span class=\"t\" lang=\"es\">Luna de la Tierra</span><span class=\"t\" lang=\"pt\">Lua da Terra</span><span class=\"t\" lang=\"fr\">Lune de la Terre</span><span class=\"t\" lang=\"ar\">قمر الأرض</span></p></div></div>","body":"<div class=\"stats\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">3,475 km</span><span class=\"t\" lang=\"hi\">3,475 किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Diameter</span><span class=\"t\" lang=\"hi\">व्यास</span><span class=\"t\" lang=\"es\">Diámetro</span><span class=\"t\" lang=\"pt\">Diâmetro</span><span class=\"t\" lang=\"fr\">Diamètre</span><span class=\"t\" lang=\"ar\">القطر</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">1.6 m/s² (0.17 g)</span><span class=\"t\" lang=\"hi\">1.6 m/s² (0.17 g)</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Gravity</span><span class=\"t\" lang=\"hi\">गुरुत्वाकर्षण</span><span class=\"t\" lang=\"es\">Gravedad</span><span class=\"t\" lang=\"pt\">Gravidade</span><span class=\"t\" lang=\"fr\">Gravité</span><span class=\"t\" lang=\"ar\">الجاذبية</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">-23 °C</span><span class=\"t\" lang=\"hi\">-23 °C</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Average temperature</span><span class=\"t\" lang=\"hi\">औसत तापमान</span><span class=\"t\" lang=\"es\">Temperatura media</span><span class=\"t\" lang=\"pt\">Temperatura média</span><span class=\"t\" lang=\"fr\">Température moyenne</span><span class=\"t\" lang=\"ar\">متوسط الحرارة</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">29.5 days</span><span class=\"t\" lang=\"hi\">29.5 दिन</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Day</span><span class=\"t\" lang=\"hi\">दिन</span><span class=\"t\" lang=\"es\">Día</span><span class=\"t\" lang=\"pt\">Dia</span><span class=\"t\" lang=\"fr\">Jour</span><span class=\"t\" lang=\"ar\">اليوم</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">27.3 days</span><span class=\"t\" lang=\"hi\">27.3 दिन</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">One orbit</span><span class=\"t\" lang=\"hi\">एक परिक्रमा</span><span class=\"t\" lang=\"es\">Una órbita</span><span class=\"t\" lang=\"pt\">Uma órbita</span><span class=\"t\" lang=\"fr\">Une orbite</span><span class=\"t\" lang=\"ar\">مدار واحد</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">149.6 million km</span><span class=\"t\" lang=\"hi\">149.6 मिलियन किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Distance from the Sun</span><span class=\"t\" lang=\"hi\">सूर्य से दूरी</span><span class=\"t\" lang=\"es\">Distancia al Sol</span><span class=\"t\" lang=\"pt\">Distância do Sol</span><span class=\"t\" lang=\"fr\">Distance du Soleil</span><span class=\"t\" lang=\"ar\">البعد عن الشمس</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">384,400 km</span><span class=\"t\" lang=\"hi\">3,84,400 किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Distance from Earth</span><span class=\"t\" lang=\"hi\">पृथ्वी से दूरी</span><span class=\"t\" lang=\"es\">Distancia a la Tierra</span><span class=\"t\" lang=\"pt\">Distância da Terra</span><span class=\"t\" lang=\"fr\">Distance de la Terre</span><span class=\"t\" lang=\"ar\">البعد عن الأرض</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">≈ 0 bar</span><span class=\"t\" lang=\"hi\">≈ 0 bar</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Surface pressure</span><span class=\"t\" lang=\"hi\">सतह का दबाव</span><span class=\"t\" lang=\"es\">Presión en la superficie</span><span class=\"t\" lang=\"pt\">Pressão na superfície</span><span class=\"t\" lang=\"fr\">Pression à la surface</span><span class=\"t\" lang=\"ar\">الضغط على السطح</span></span></div></div><h3><span class=\"t\" lang=\"en\">When and how it formed</span><span class=\"t\" lang=\"hi\">कब और कैसे बना</span></h3><div class=\"formhead\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">About 4.5 billion years ago</span><span class=\"t\" lang=\"hi\">लगभग 4.5 अरब साल पहले</span></b><span><span class=\"t\" lang=\"en\">Formed</span><span class=\"t\" lang=\"hi\">कब बना</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">Very fast: perhaps hours to a few years</span><span class=\"t\" lang=\"hi\">बहुत तेज़ी से: शायद कुछ घंटों से कुछ सालों में</span></b><span><span class=\"t\" lang=\"en\">How long it took</span><span class=\"t\" lang=\"hi\">कितना समय लगा</span></span></div></div><p><span class=\"t\" lang=\"en\">A Mars-sized body called Theia hit the young Earth. Molten rock was thrown into orbit and gathered into the Moon. Apollo rocks have almost the same make-up as Earth&amp;#x27;s rocks, which supports this idea.</span><span class=\"t\" lang=\"hi\">मंगल जितना बड़ा एक पिंड, Theia, नई पृथ्वी से टकराया। पिघली चट्टान कक्षा में उछली और जुड़कर चाँद बनी। Apollo की चट्टानें लगभग पृथ्वी की चट्टानों जैसी हैं, जो इस विचार का समर्थन करता है।</span></p><div class=\"tl formtl\"><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">About 4.5 billion years ago</span><span class=\"t\" lang=\"hi\">लगभग 4.5 अरब साल पहले</span></div><p><span class=\"t\" lang=\"en\">The giant impact; a ring of molten debris circles Earth and clumps into the Moon.</span><span class=\"t\" lang=\"hi\">बड़ी टक्कर; पिघले मलबे का छल्ला पृथ्वी के चारों ओर घूमता है और जुड़कर चाँद बनता है।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Next ~100 million years</span><span class=\"t\" lang=\"hi\">अगले लगभग 10 करोड़ साल</span></div><p><span class=\"t\" lang=\"en\">A global ocean of magma cools; light rock floats up to form the bright highlands.</span><span class=\"t\" lang=\"hi\">magma का पूरा समुद्र ठंडा होता है; हल्की चट्टान ऊपर तैरकर चमकीले पहाड़ी इलाक़े बनाती है।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">About 3.9 to 3.1 billion years ago</span><span class=\"t\" lang=\"hi\">लगभग 3.9 से 3.1 अरब साल पहले</span></div><p><span class=\"t\" lang=\"en\">Lava fills huge impact basins, making the dark &amp;quot;seas&amp;quot; (maria) we see.</span><span class=\"t\" lang=\"hi\">लावा बड़े गड्ढों को भरता है और वे काले &amp;quot;समुद्र&amp;quot; (maria) बनते हैं जो हमें दिखते हैं।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Since then</span><span class=\"t\" lang=\"hi\">तब से</span></div><p><span class=\"t\" lang=\"en\">Mostly quiet; the Moon drifts away from Earth by about 3.8 cm a year.</span><span class=\"t\" lang=\"hi\">ज़्यादातर शांत; चाँद हर साल लगभग 3.8 cm पृथ्वी से दूर जाता है।</span></p></div></div><div class=\"callout\">❓ <b><span class=\"t\" lang=\"en\">Still unknown</span><span class=\"t\" lang=\"hi\">अभी भी अनजाना</span>:</b> <span class=\"t\" lang=\"en\">The details of the impact are still argued: how big Theia was, how fast it hit, and why the Moon&amp;#x27;s rocks match Earth&amp;#x27;s so closely.</span><span class=\"t\" lang=\"hi\">टक्कर की बारीकियों पर अभी भी बहस है: Theia कितना बड़ा था, कितनी तेज़ी से टकराया, और चाँद की चट्टानें पृथ्वी जैसी इतनी क्यों हैं।</span></div><p class=\"note\"><span class=\"t\" lang=\"en\">All dates are estimates from meteorites, moon rocks, space missions and computer models.</span><span class=\"t\" lang=\"hi\">सभी तारीख़ें अनुमान हैं, जो उल्कापिंडों, चाँद की चट्टानों, अंतरिक्ष missions और computer models से आती हैं।</span></p><h3><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Did you know?</span><span class=\"t\" lang=\"hi\">क्या आप जानते हैं?</span><span class=\"t\" lang=\"es\">¿Sabías que…?</span><span class=\"t\" lang=\"pt\">Você sabia?</span><span class=\"t\" lang=\"fr\">Le saviez-vous ?</span><span class=\"t\" lang=\"ar\">هل تعلم؟</span></h3><ul class=\"sheetfacts\"><li><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">The Moon moves about 3.8 centimetres farther from Earth every year.</span><span class=\"t\" lang=\"hi\">चंद्रमा हर साल पृथ्वी से करीब 3.8 सेंटीमीटर और दूर चला जाता है।</span><span class=\"t\" lang=\"es\">La Luna se aleja de la Tierra unos 3,8 centímetros cada año.</span><span class=\"t\" lang=\"pt\">A Lua se afasta da Terra cerca de 3,8 centímetros por ano.</span><span class=\"t\" lang=\"fr\">La Lune s&#x27;éloigne de la Terre d&#x27;environ 3,8 centimètres par an.</span><span class=\"t\" lang=\"ar\">يبتعد القمر عن الأرض نحو 3.8 سنتيمتر كل عام.</span></li><li><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">We always see the same side of the Moon, because it turns exactly once for each trip around Earth.</span><span class=\"t\" lang=\"hi\">हमें चंद्रमा का हमेशा एक ही हिस्सा दिखता है, क्योंकि वह पृथ्वी के हर चक्कर में ठीक एक बार घूमता है।</span><span class=\"t\" lang=\"es\">Siempre vemos la misma cara de la Luna, porque gira exactamente una vez por cada vuelta alrededor de la Tierra.</span><span class=\"t\" lang=\"pt\">Sempre vemos o mesmo lado da Lua, porque ela gira exatamente uma vez a cada volta em torno da Terra.</span><span class=\"t\" lang=\"fr\">Nous voyons toujours la même face de la Lune, car elle tourne exactement une fois à chaque tour autour de la Terre.</span><span class=\"t\" lang=\"ar\">نرى دائمًا الوجه نفسه من القمر، لأنه يدور حول نفسه مرة واحدة بالضبط مع كل دورة حول الأرض.</span></li></ul><p><a class=\"btn primary\" href=\"body/moon.html\" data-full><span class=\"t\" lang=\"en\">Full page: layers, telescope view, atmosphere</span><span class=\"t\" lang=\"hi\">पूरा page: परतें, दूरबीन का दृश्य, वायुमंडल</span> →</a></p>"},"io":{"head":"<div class=\"sheethead\"><img class=\"pimg\" src=\"img/planets/io.webp\" alt=\"Io\" width=\"600\" height=\"600\" loading=\"eager\" decoding=\"async\"><div><h2 id=\"sheetTitle\"><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Io</span><span class=\"t\" lang=\"hi\">आयो</span><span class=\"t\" lang=\"es\">Ío</span><span class=\"t\" lang=\"pt\">Io</span><span class=\"t\" lang=\"fr\">Io</span><span class=\"t\" lang=\"ar\">آيو</span></h2><p class=\"sub\"><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Moon of Jupiter</span><span class=\"t\" lang=\"hi\">बृहस्पति का चंद्रमा</span><span class=\"t\" lang=\"es\">Luna de Júpiter</span><span class=\"t\" lang=\"pt\">Lua de Júpiter</span><span class=\"t\" lang=\"fr\">Lune de Jupiter</span><span class=\"t\" lang=\"ar\">قمر المشتري</span></p></div></div>","body":"<div class=\"stats\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">3,643 km</span><span class=\"t\" lang=\"hi\">3,643 किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Diameter</span><span class=\"t\" lang=\"hi\">व्यास</span><span class=\"t\" lang=\"es\">Diámetro</span><span class=\"t\" lang=\"pt\">Diâmetro</span><span class=\"t\" lang=\"fr\">Diamètre</span><span class=\"t\" lang=\"ar\">القطر</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">1.8 m/s² (0.18 g)</span><span class=\"t\" lang=\"hi\">1.8 m/s² (0.18 g)</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Gravity</span><span class=\"t\" lang=\"hi\">गुरुत्वाकर्षण</span><span class=\"t\" lang=\"es\">Gravedad</span><span class=\"t\" lang=\"pt\">Gravidade</span><span class=\"t\" lang=\"fr\">Gravité</span><span class=\"t\" lang=\"ar\">الجاذبية</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">-143 °C</span><span class=\"t\" lang=\"hi\">-143 °C</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Average temperature</span><span class=\"t\" lang=\"hi\">औसत तापमान</span><span class=\"t\" lang=\"es\">Temperatura media</span><span class=\"t\" lang=\"pt\">Temperatura média</span><span class=\"t\" lang=\"fr\">Température moyenne</span><span class=\"t\" lang=\"ar\">متوسط الحرارة</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">42.5 h</span><span class=\"t\" lang=\"hi\">42.5 घंटे</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Day</span><span class=\"t\" lang=\"hi\">दिन</span><span class=\"t\" lang=\"es\">Día</span><span class=\"t\" lang=\"pt\">Dia</span><span class=\"t\" lang=\"fr\">Jour</span><span class=\"t\" lang=\"ar\">اليوم</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">1.8 days</span><span class=\"t\" lang=\"hi\">1.8 दिन</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">One orbit</span><span class=\"t\" lang=\"hi\">एक परिक्रमा</span><span class=\"t\" lang=\"es\">Una órbita</span><span class=\"t\" lang=\"pt\">Uma órbita</span><span class=\"t\" lang=\"fr\">Une orbite</span><span class=\"t\" lang=\"ar\">مدار واحد</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">778.5 million km</span><span class=\"t\" lang=\"hi\">778.5 मिलियन किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Distance from the Sun</span><span class=\"t\" lang=\"hi\">सूर्य से दूरी</span><span class=\"t\" lang=\"es\">Distancia al Sol</span><span class=\"t\" lang=\"pt\">Distância do Sol</span><span class=\"t\" lang=\"fr\">Distance du Soleil</span><span class=\"t\" lang=\"ar\">البعد عن الشمس</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">421,700 km</span><span class=\"t\" lang=\"hi\">4,21,700 किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Distance from Jupiter</span><span class=\"t\" lang=\"hi\">बृहस्पति से दूरी</span><span class=\"t\" lang=\"es\">Distancia a Júpiter</span><span class=\"t\" lang=\"pt\">Distância de Júpiter</span><span class=\"t\" lang=\"fr\">Distance de Jupiter</span><span class=\"t\" lang=\"ar\">البعد عن المشتري</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">≈ 0 bar</span><span class=\"t\" lang=\"hi\">≈ 0 bar</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Surface pressure</span><span class=\"t\" lang=\"hi\">सतह का दबाव</span><span class=\"t\" lang=\"es\">Presión en la superficie</span><span class=\"t\" lang=\"pt\">Pressão na superfície</span><span class=\"t\" lang=\"fr\">Pression à la surface</span><span class=\"t\" lang=\"ar\">الضغط على السطح</span></span></div></div><h3><span class=\"t\" lang=\"en\">When and how it formed</span><span class=\"t\" lang=\"hi\">कब और कैसे बना</span></h3><div class=\"formhead\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">About 4.6 billion years ago, with Jupiter</span><span class=\"t\" lang=\"hi\">लगभग 4.6 अरब साल पहले, बृहस्पति के साथ</span></b><span><span class=\"t\" lang=\"en\">Formed</span><span class=\"t\" lang=\"hi\">कब बना</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">Within the first few million years</span><span class=\"t\" lang=\"hi\">पहले कुछ लाख साल में</span></b><span><span class=\"t\" lang=\"en\">How long it took</span><span class=\"t\" lang=\"hi\">कितना समय लगा</span></span></div></div><p><span class=\"t\" lang=\"en\">Io formed from a disk of gas and dust around the young Jupiter, like a small solar system. Its orbit is locked in step with Europa and Ganymede, so Jupiter&amp;#x27;s gravity keeps squeezing it, heating its inside. That is why Io has more volcanoes than any other world.</span><span class=\"t\" lang=\"hi\">Io नए बृहस्पति के चारों ओर गैस और धूल की disk से बना, एक छोटे सौरमंडल की तरह। इसकी कक्षा Europa और Ganymede की लय से बँधी है, इसलिए बृहस्पति की gravity इसे लगातार दबाती है और अंदर से गर्म करती है। इसीलिए Io पर किसी भी दुनिया से ज़्यादा ज्वालामुखी हैं।</span></p><div class=\"tl formtl\"><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">First few million years</span><span class=\"t\" lang=\"hi\">पहले कुछ लाख साल</span></div><p><span class=\"t\" lang=\"en\">Rock and dust near Jupiter gather into Io.</span><span class=\"t\" lang=\"hi\">बृहस्पति के पास चट्टान और धूल जुड़कर Io बनाती है।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Early on</span><span class=\"t\" lang=\"hi\">शुरुआत में</span></div><p><span class=\"t\" lang=\"en\">Io, Europa and Ganymede fall into a 1:2:4 rhythm of orbits.</span><span class=\"t\" lang=\"hi\">Io, Europa और Ganymede कक्षाओं की 1:2:4 लय में आ जाते हैं।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Ever since</span><span class=\"t\" lang=\"hi\">तब से</span></div><p><span class=\"t\" lang=\"en\">Tidal squeezing melts rock; about 400 volcanoes erupt, and the surface is renewed all the time.</span><span class=\"t\" lang=\"hi\">ज्वारीय दबाव चट्टान पिघलाता है; लगभग 400 ज्वालामुखी फटते हैं और सतह लगातार नई होती रहती है।</span></p></div></div><p class=\"note\"><span class=\"t\" lang=\"en\">All dates are estimates from meteorites, moon rocks, space missions and computer models.</span><span class=\"t\" lang=\"hi\">सभी तारीख़ें अनुमान हैं, जो उल्कापिंडों, चाँद की चट्टानों, अंतरिक्ष missions और computer models से आती हैं।</span></p><h3><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Did you know?</span><span class=\"t\" lang=\"hi\">क्या आप जानते हैं?</span><span class=\"t\" lang=\"es\">¿Sabías que…?</span><span class=\"t\" lang=\"pt\">Você sabia?</span><span class=\"t\" lang=\"fr\">Le saviez-vous ?</span><span class=\"t\" lang=\"ar\">هل تعلم؟</span></h3><ul class=\"sheetfacts\"><li><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Io is the most volcanic world we know, with hundreds of active volcanoes.</span><span class=\"t\" lang=\"hi\">आयो हमारी जानकारी की सबसे ज़्यादा ज्वालामुखी वाली दुनिया है, जहाँ सैकड़ों सक्रिय ज्वालामुखी हैं।</span><span class=\"t\" lang=\"es\">Ío es el mundo más volcánico que conocemos, con cientos de volcanes activos.</span><span class=\"t\" lang=\"pt\">Io é o mundo mais vulcânico que conhecemos, com centenas de vulcões ativos.</span><span class=\"t\" lang=\"fr\">Io est le monde le plus volcanique que nous connaissions, avec des centaines de volcans actifs.</span><span class=\"t\" lang=\"ar\">آيو أكثر عالم بركاني نعرفه، وفيه مئات البراكين النشطة.</span></li><li><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Jupiter&#x27;s gravity squeezes and stretches Io, and the heat from this powers its volcanoes.</span><span class=\"t\" lang=\"hi\">बृहस्पति का गुरुत्वाकर्षण आयो को दबाता और खींचता है, और इससे पैदा गर्मी उसके ज्वालामुखियों को चलाती है।</span><span class=\"t\" lang=\"es\">La gravedad de Júpiter comprime y estira a Ío, y el calor que eso produce alimenta sus volcanes.</span><span class=\"t\" lang=\"pt\">A gravidade de Júpiter comprime e estica Io, e o calor disso alimenta seus vulcões.</span><span class=\"t\" lang=\"fr\">La gravité de Jupiter comprime et étire Io, et la chaleur ainsi produite alimente ses volcans.</span><span class=\"t\" lang=\"ar\">تضغط جاذبية المشتري آيو وتمدّه، والحرارة الناتجة عن ذلك تغذي براكينه.</span></li></ul><p><a class=\"btn primary\" href=\"body/io.html\" data-full><span class=\"t\" lang=\"en\">Full page: layers, telescope view, atmosphere</span><span class=\"t\" lang=\"hi\">पूरा page: परतें, दूरबीन का दृश्य, वायुमंडल</span> →</a></p>"},"europa":{"head":"<div class=\"sheethead\"><img class=\"pimg\" src=\"img/planets/europa.webp\" alt=\"Europa\" width=\"600\" height=\"600\" loading=\"eager\" decoding=\"async\"><div><h2 id=\"sheetTitle\"><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Europa</span><span class=\"t\" lang=\"hi\">यूरोपा</span><span class=\"t\" lang=\"es\">Europa</span><span class=\"t\" lang=\"pt\">Europa</span><span class=\"t\" lang=\"fr\">Europe</span><span class=\"t\" lang=\"ar\">أوروبا</span></h2><p class=\"sub\"><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Moon of Jupiter</span><span class=\"t\" lang=\"hi\">बृहस्पति का चंद्रमा</span><span class=\"t\" lang=\"es\">Luna de Júpiter</span><span class=\"t\" lang=\"pt\">Lua de Júpiter</span><span class=\"t\" lang=\"fr\">Lune de Jupiter</span><span class=\"t\" lang=\"ar\">قمر المشتري</span></p></div></div>","body":"<div class=\"stats\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">3,122 km</span><span class=\"t\" lang=\"hi\">3,122 किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Diameter</span><span class=\"t\" lang=\"hi\">व्यास</span><span class=\"t\" lang=\"es\">Diámetro</span><span class=\"t\" lang=\"pt\">Diâmetro</span><span class=\"t\" lang=\"fr\">Diamètre</span><span class=\"t\" lang=\"ar\">القطر</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">1.3 m/s² (0.13 g)</span><span class=\"t\" lang=\"hi\">1.3 m/s² (0.13 g)</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Gravity</span><span class=\"t\" lang=\"hi\">गुरुत्वाकर्षण</span><span class=\"t\" lang=\"es\">Gravedad</span><span class=\"t\" lang=\"pt\">Gravidade</span><span class=\"t\" lang=\"fr\">Gravité</span><span class=\"t\" lang=\"ar\">الجاذبية</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">-160 °C</span><span class=\"t\" lang=\"hi\">-160 °C</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Average temperature</span><span class=\"t\" lang=\"hi\">औसत तापमान</span><span class=\"t\" lang=\"es\">Temperatura media</span><span class=\"t\" lang=\"pt\">Temperatura média</span><span class=\"t\" lang=\"fr\">Température moyenne</span><span class=\"t\" lang=\"ar\">متوسط الحرارة</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">3.6 days</span><span class=\"t\" lang=\"hi\">3.6 दिन</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Day</span><span class=\"t\" lang=\"hi\">दिन</span><span class=\"t\" lang=\"es\">Día</span><span class=\"t\" lang=\"pt\">Dia</span><span class=\"t\" lang=\"fr\">Jour</span><span class=\"t\" lang=\"ar\">اليوم</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">3.5 days</span><span class=\"t\" lang=\"hi\">3.5 दिन</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">One orbit</span><span class=\"t\" lang=\"hi\">एक परिक्रमा</span><span class=\"t\" lang=\"es\">Una órbita</span><span class=\"t\" lang=\"pt\">Uma órbita</span><span class=\"t\" lang=\"fr\">Une orbite</span><span class=\"t\" lang=\"ar\">مدار واحد</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">778.5 million km</span><span class=\"t\" lang=\"hi\">778.5 मिलियन किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Distance from the Sun</span><span class=\"t\" lang=\"hi\">सूर्य से दूरी</span><span class=\"t\" lang=\"es\">Distancia al Sol</span><span class=\"t\" lang=\"pt\">Distância do Sol</span><span class=\"t\" lang=\"fr\">Distance du Soleil</span><span class=\"t\" lang=\"ar\">البعد عن الشمس</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">670,900 km</span><span class=\"t\" lang=\"hi\">6,70,900 किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Distance from Jupiter</span><span class=\"t\" lang=\"hi\">बृहस्पति से दूरी</span><span class=\"t\" lang=\"es\">Distancia a Júpiter</span><span class=\"t\" lang=\"pt\">Distância de Júpiter</span><span class=\"t\" lang=\"fr\">Distance de Jupiter</span><span class=\"t\" lang=\"ar\">البعد عن المشتري</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">≈ 0 bar</span><span class=\"t\" lang=\"hi\">≈ 0 bar</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Surface pressure</span><span class=\"t\" lang=\"hi\">सतह का दबाव</span><span class=\"t\" lang=\"es\">Presión en la superficie</span><span class=\"t\" lang=\"pt\">Pressão na superfície</span><span class=\"t\" lang=\"fr\">Pression à la surface</span><span class=\"t\" lang=\"ar\">الضغط على السطح</span></span></div></div><h3><span class=\"t\" lang=\"en\">When and how it formed</span><span class=\"t\" lang=\"hi\">कब और कैसे बना</span></h3><div class=\"formhead\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">About 4.6 billion years ago, with Jupiter</span><span class=\"t\" lang=\"hi\">लगभग 4.6 अरब साल पहले, बृहस्पति के साथ</span></b><span><span class=\"t\" lang=\"en\">Formed</span><span class=\"t\" lang=\"hi\">कब बना</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">Within the first few million years</span><span class=\"t\" lang=\"hi\">पहले कुछ लाख साल में</span></b><span><span class=\"t\" lang=\"en\">How long it took</span><span class=\"t\" lang=\"hi\">कितना समय लगा</span></span></div></div><p><span class=\"t\" lang=\"en\">Europa formed from rock and ice in the disk around Jupiter. Heat from tidal squeezing keeps a salty ocean liquid under its icy shell. Its surface has few craters, so the ice is young, perhaps 40 to 90 million years.</span><span class=\"t\" lang=\"hi\">Europa बृहस्पति के चारों ओर की disk में चट्टान और बर्फ़ से बना। ज्वारीय दबाव की गर्मी इसकी बर्फ़ीली परत के नीचे एक खारे समुद्र को तरल रखती है। सतह पर गड्ढे कम हैं, इसलिए बर्फ़ नई है, शायद 4 से 9 करोड़ साल पुरानी।</span></p><div class=\"tl formtl\"><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">First few million years</span><span class=\"t\" lang=\"hi\">पहले कुछ लाख साल</span></div><p><span class=\"t\" lang=\"en\">Rock and ice gather; a rocky core forms with water on top.</span><span class=\"t\" lang=\"hi\">चट्टान और बर्फ़ जुड़ते हैं; पथरीला core बनता है और ऊपर पानी।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Early on</span><span class=\"t\" lang=\"hi\">शुरुआत में</span></div><p><span class=\"t\" lang=\"en\">The outer water freezes into a shell, with an ocean left below.</span><span class=\"t\" lang=\"hi\">बाहरी पानी जमकर परत बनता है, नीचे समुद्र बच जाता है।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Last ~100 million years</span><span class=\"t\" lang=\"hi\">पिछले लगभग 10 करोड़ साल</span></div><p><span class=\"t\" lang=\"en\">Cracks and ridges keep renewing the ice; plumes of water may escape.</span><span class=\"t\" lang=\"hi\">दरारें और लकीरें बर्फ़ को नया करती रहती हैं; पानी की धाराएँ शायद बाहर निकलती हैं।</span></p></div></div><div class=\"callout\">❓ <b><span class=\"t\" lang=\"en\">Still unknown</span><span class=\"t\" lang=\"hi\">अभी भी अनजाना</span>:</b> <span class=\"t\" lang=\"en\">Could the ocean hold life? NASA&amp;#x27;s Europa Clipper, launched in 2024, arrives in 2030 to study it.</span><span class=\"t\" lang=\"hi\">क्या समुद्र में जीवन हो सकता है? NASA का Europa Clipper, 2024 में launch हुआ, 2030 में पहुँचकर इसकी जाँच करेगा।</span></div><p class=\"note\"><span class=\"t\" lang=\"en\">All dates are estimates from meteorites, moon rocks, space missions and computer models.</span><span class=\"t\" lang=\"hi\">सभी तारीख़ें अनुमान हैं, जो उल्कापिंडों, चाँद की चट्टानों, अंतरिक्ष missions और computer models से आती हैं।</span></p><h3><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Did you know?</span><span class=\"t\" lang=\"hi\">क्या आप जानते हैं?</span><span class=\"t\" lang=\"es\">¿Sabías que…?</span><span class=\"t\" lang=\"pt\">Você sabia?</span><span class=\"t\" lang=\"fr\">Le saviez-vous ?</span><span class=\"t\" lang=\"ar\">هل تعلم؟</span></h3><ul class=\"sheetfacts\"><li><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Under its icy shell, Europa probably holds about twice as much water as all of Earth&#x27;s oceans.</span><span class=\"t\" lang=\"hi\">अपनी बर्फ़ीली परत के नीचे यूरोपा में शायद पृथ्वी के सभी महासागरों से करीब दोगुना पानी है।</span><span class=\"t\" lang=\"es\">Bajo su corteza helada, Europa probablemente contiene el doble de agua que todos los océanos de la Tierra.</span><span class=\"t\" lang=\"pt\">Sob a crosta de gelo, Europa provavelmente guarda cerca do dobro de água de todos os oceanos da Terra.</span><span class=\"t\" lang=\"fr\">Sous sa croûte de glace, Europe contient probablement environ deux fois plus d&#x27;eau que tous les océans de la Terre.</span><span class=\"t\" lang=\"ar\">تحت قشرته الجليدية، يحتوي أوروبا على ما يقارب ضعف ماء محيطات الأرض كلها.</span></li><li><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Europa is one of the best places to look for life beyond Earth. The Europa Clipper spacecraft is on its way there.</span><span class=\"t\" lang=\"hi\">यूरोपा पृथ्वी से परे जीवन खोजने की सबसे अच्छी जगहों में से एक है। यूरोपा क्लिपर यान वहाँ जा रहा है।</span><span class=\"t\" lang=\"es\">Europa es uno de los mejores lugares donde buscar vida más allá de la Tierra. La nave Europa Clipper va camino de allí.</span><span class=\"t\" lang=\"pt\">Europa é um dos melhores lugares para procurar vida além da Terra. A sonda Europa Clipper está a caminho.</span><span class=\"t\" lang=\"fr\">Europe est l&#x27;un des meilleurs endroits où chercher de la vie au-delà de la Terre. La sonde Europa Clipper y est en route.</span><span class=\"t\" lang=\"ar\">أوروبا من أفضل الأماكن للبحث عن حياة خارج الأرض. والمركبة Europa Clipper في طريقها إليه.</span></li></ul><p><a class=\"btn primary\" href=\"body/europa.html\" data-full><span class=\"t\" lang=\"en\">Full page: layers, telescope view, atmosphere</span><span class=\"t\" lang=\"hi\">पूरा page: परतें, दूरबीन का दृश्य, वायुमंडल</span> →</a></p>"},"ganymede":{"head":"<div class=\"sheethead\"><img class=\"pimg\" src=\"img/planets/ganymede.webp\" alt=\"Ganymede\" width=\"600\" height=\"600\" loading=\"eager\" decoding=\"async\"><div><h2 id=\"sheetTitle\"><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Ganymede</span><span class=\"t\" lang=\"hi\">गैनिमीड</span><span class=\"t\" lang=\"es\">Ganímedes</span><span class=\"t\" lang=\"pt\">Ganimedes</span><span class=\"t\" lang=\"fr\">Ganymède</span><span class=\"t\" lang=\"ar\">غانيميد</span></h2><p class=\"sub\"><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Moon of Jupiter</span><span class=\"t\" lang=\"hi\">बृहस्पति का चंद्रमा</span><span class=\"t\" lang=\"es\">Luna de Júpiter</span><span class=\"t\" lang=\"pt\">Lua de Júpiter</span><span class=\"t\" lang=\"fr\">Lune de Jupiter</span><span class=\"t\" lang=\"ar\">قمر المشتري</span></p></div></div>","body":"<div class=\"stats\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">5,268 km</span><span class=\"t\" lang=\"hi\">5,268 किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Diameter</span><span class=\"t\" lang=\"hi\">व्यास</span><span class=\"t\" lang=\"es\">Diámetro</span><span class=\"t\" lang=\"pt\">Diâmetro</span><span class=\"t\" lang=\"fr\">Diamètre</span><span class=\"t\" lang=\"ar\">القطر</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">1.4 m/s² (0.15 g)</span><span class=\"t\" lang=\"hi\">1.4 m/s² (0.15 g)</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Gravity</span><span class=\"t\" lang=\"hi\">गुरुत्वाकर्षण</span><span class=\"t\" lang=\"es\">Gravedad</span><span class=\"t\" lang=\"pt\">Gravidade</span><span class=\"t\" lang=\"fr\">Gravité</span><span class=\"t\" lang=\"ar\">الجاذبية</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">-163 °C</span><span class=\"t\" lang=\"hi\">-163 °C</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Average temperature</span><span class=\"t\" lang=\"hi\">औसत तापमान</span><span class=\"t\" lang=\"es\">Temperatura media</span><span class=\"t\" lang=\"pt\">Temperatura média</span><span class=\"t\" lang=\"fr\">Température moyenne</span><span class=\"t\" lang=\"ar\">متوسط الحرارة</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">7.2 days</span><span class=\"t\" lang=\"hi\">7.2 दिन</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Day</span><span class=\"t\" lang=\"hi\">दिन</span><span class=\"t\" lang=\"es\">Día</span><span class=\"t\" lang=\"pt\">Dia</span><span class=\"t\" lang=\"fr\">Jour</span><span class=\"t\" lang=\"ar\">اليوم</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">7.2 days</span><span class=\"t\" lang=\"hi\">7.2 दिन</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">One orbit</span><span class=\"t\" lang=\"hi\">एक परिक्रमा</span><span class=\"t\" lang=\"es\">Una órbita</span><span class=\"t\" lang=\"pt\">Uma órbita</span><span class=\"t\" lang=\"fr\">Une orbite</span><span class=\"t\" lang=\"ar\">مدار واحد</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">778.5 million km</span><span class=\"t\" lang=\"hi\">778.5 मिलियन किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Distance from the Sun</span><span class=\"t\" lang=\"hi\">सूर्य से दूरी</span><span class=\"t\" lang=\"es\">Distancia al Sol</span><span class=\"t\" lang=\"pt\">Distância do Sol</span><span class=\"t\" lang=\"fr\">Distance du Soleil</span><span class=\"t\" lang=\"ar\">البعد عن الشمس</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">1,070,400 km</span><span class=\"t\" lang=\"hi\">10,70,400 किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Distance from Jupiter</span><span class=\"t\" lang=\"hi\">बृहस्पति से दूरी</span><span class=\"t\" lang=\"es\">Distancia a Júpiter</span><span class=\"t\" lang=\"pt\">Distância de Júpiter</span><span class=\"t\" lang=\"fr\">Distance de Jupiter</span><span class=\"t\" lang=\"ar\">البعد عن المشتري</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">≈ 0 bar</span><span class=\"t\" lang=\"hi\">≈ 0 bar</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Surface pressure</span><span class=\"t\" lang=\"hi\">सतह का दबाव</span><span class=\"t\" lang=\"es\">Presión en la superficie</span><span class=\"t\" lang=\"pt\">Pressão na superfície</span><span class=\"t\" lang=\"fr\">Pression à la surface</span><span class=\"t\" lang=\"ar\">الضغط على السطح</span></span></div></div><h3><span class=\"t\" lang=\"en\">When and how it formed</span><span class=\"t\" lang=\"hi\">कब और कैसे बना</span></h3><div class=\"formhead\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">About 4.6 billion years ago, with Jupiter</span><span class=\"t\" lang=\"hi\">लगभग 4.6 अरब साल पहले, बृहस्पति के साथ</span></b><span><span class=\"t\" lang=\"en\">Formed</span><span class=\"t\" lang=\"hi\">कब बना</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">Within the first few million years</span><span class=\"t\" lang=\"hi\">पहले कुछ लाख साल में</span></b><span><span class=\"t\" lang=\"en\">How long it took</span><span class=\"t\" lang=\"hi\">कितना समय लगा</span></span></div></div><p><span class=\"t\" lang=\"en\">The biggest moon in the solar system formed from rock and ice around Jupiter. It got warm enough inside to separate into layers, with an iron core that still makes its own magnetic field, the only moon known to have one.</span><span class=\"t\" lang=\"hi\">सौरमंडल का सबसे बड़ा चाँद बृहस्पति के चारों ओर चट्टान और बर्फ़ से बना। यह अंदर से इतना गर्म हुआ कि परतों में बँट गया, और इसका लोहे का core आज भी अपना magnetic field बनाता है। यह अकेला ज्ञात चाँद है जिसके पास यह है।</span></p><div class=\"tl formtl\"><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">First few million years</span><span class=\"t\" lang=\"hi\">पहले कुछ लाख साल</span></div><p><span class=\"t\" lang=\"en\">Rock and ice gather into a huge moon.</span><span class=\"t\" lang=\"hi\">चट्टान और बर्फ़ जुड़कर एक विशाल चाँद बनाते हैं।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Early on</span><span class=\"t\" lang=\"hi\">शुरुआत में</span></div><p><span class=\"t\" lang=\"en\">It separates into an iron core, a rocky layer, ice and a deep ocean.</span><span class=\"t\" lang=\"hi\">यह लोहे के core, पथरीली परत, बर्फ़ और गहरे समुद्र में बँट जाता है।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Billions of years</span><span class=\"t\" lang=\"hi\">अरबों साल</span></div><p><span class=\"t\" lang=\"en\">Old dark areas and younger grooved bright areas form on the surface.</span><span class=\"t\" lang=\"hi\">सतह पर पुराने काले इलाक़े और नए, धारीदार चमकीले इलाक़े बनते हैं।</span></p></div></div><div class=\"callout\">❓ <b><span class=\"t\" lang=\"en\">Still unknown</span><span class=\"t\" lang=\"hi\">अभी भी अनजाना</span>:</b> <span class=\"t\" lang=\"en\">ESA&amp;#x27;s JUICE spacecraft, launched in 2023, will orbit Ganymede from 2034 to study its hidden ocean.</span><span class=\"t\" lang=\"hi\">ESA का JUICE यान, 2023 में launch हुआ, 2034 से Ganymede की परिक्रमा करके उसका छिपा समुद्र पढ़ेगा।</span></div><p class=\"note\"><span class=\"t\" lang=\"en\">All dates are estimates from meteorites, moon rocks, space missions and computer models.</span><span class=\"t\" lang=\"hi\">सभी तारीख़ें अनुमान हैं, जो उल्कापिंडों, चाँद की चट्टानों, अंतरिक्ष missions और computer models से आती हैं।</span></p><h3><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Did you know?</span><span class=\"t\" lang=\"hi\">क्या आप जानते हैं?</span><span class=\"t\" lang=\"es\">¿Sabías que…?</span><span class=\"t\" lang=\"pt\">Você sabia?</span><span class=\"t\" lang=\"fr\">Le saviez-vous ?</span><span class=\"t\" lang=\"ar\">هل تعلم؟</span></h3><ul class=\"sheetfacts\"><li><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Ganymede is the largest moon in the solar system. It is even bigger than Mercury.</span><span class=\"t\" lang=\"hi\">गैनिमीड सौरमंडल का सबसे बड़ा चंद्रमा है। वह बुध से भी बड़ा है।</span><span class=\"t\" lang=\"es\">Ganímedes es la luna más grande del sistema solar. Es incluso mayor que Mercurio.</span><span class=\"t\" lang=\"pt\">Ganimedes é a maior lua do Sistema Solar. É até maior que Mercúrio.</span><span class=\"t\" lang=\"fr\">Ganymède est la plus grande lune du système solaire. Elle est même plus grosse que Mercure.</span><span class=\"t\" lang=\"ar\">غانيميد أكبر قمر في المجموعة الشمسية. بل هو أكبر من عطارد.</span></li><li><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Ganymede is the only moon known to have a magnetic field of its own.</span><span class=\"t\" lang=\"hi\">गैनिमीड अकेला चंद्रमा है जिसका अपना चुंबकीय क्षेत्र पाया गया है।</span><span class=\"t\" lang=\"es\">Ganímedes es la única luna que se sabe que tiene campo magnético propio.</span><span class=\"t\" lang=\"pt\">Ganimedes é a única lua conhecida com campo magnético próprio.</span><span class=\"t\" lang=\"fr\">Ganymède est la seule lune connue à posséder un champ magnétique propre.</span><span class=\"t\" lang=\"ar\">غانيميد القمر الوحيد المعروف بأن له مجالًا مغناطيسيًا خاصًا به.</span></li></ul><p><a class=\"btn primary\" href=\"body/ganymede.html\" data-full><span class=\"t\" lang=\"en\">Full page: layers, telescope view, atmosphere</span><span class=\"t\" lang=\"hi\">पूरा page: परतें, दूरबीन का दृश्य, वायुमंडल</span> →</a></p>"},"callisto":{"head":"<div class=\"sheethead\"><img class=\"pimg\" src=\"img/planets/callisto.webp\" alt=\"Callisto\" width=\"600\" height=\"600\" loading=\"eager\" decoding=\"async\"><div><h2 id=\"sheetTitle\"><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Callisto</span><span class=\"t\" lang=\"hi\">कैलिस्टो</span><span class=\"t\" lang=\"es\">Calisto</span><span class=\"t\" lang=\"pt\">Calisto</span><span class=\"t\" lang=\"fr\">Callisto</span><span class=\"t\" lang=\"ar\">كاليستو</span></h2><p class=\"sub\"><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Moon of Jupiter</span><span class=\"t\" lang=\"hi\">बृहस्पति का चंद्रमा</span><span class=\"t\" lang=\"es\">Luna de Júpiter</span><span class=\"t\" lang=\"pt\">Lua de Júpiter</span><span class=\"t\" lang=\"fr\">Lune de Jupiter</span><span class=\"t\" lang=\"ar\">قمر المشتري</span></p></div></div>","body":"<div class=\"stats\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">4,821 km</span><span class=\"t\" lang=\"hi\">4,821 किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Diameter</span><span class=\"t\" lang=\"hi\">व्यास</span><span class=\"t\" lang=\"es\">Diámetro</span><span class=\"t\" lang=\"pt\">Diâmetro</span><span class=\"t\" lang=\"fr\">Diamètre</span><span class=\"t\" lang=\"ar\">القطر</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">1.2 m/s² (0.13 g)</span><span class=\"t\" lang=\"hi\">1.2 m/s² (0.13 g)</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Gravity</span><span class=\"t\" lang=\"hi\">गुरुत्वाकर्षण</span><span class=\"t\" lang=\"es\">Gravedad</span><span class=\"t\" lang=\"pt\">Gravidade</span><span class=\"t\" lang=\"fr\">Gravité</span><span class=\"t\" lang=\"ar\">الجاذبية</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">-139 °C</span><span class=\"t\" lang=\"hi\">-139 °C</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Average temperature</span><span class=\"t\" lang=\"hi\">औसत तापमान</span><span class=\"t\" lang=\"es\">Temperatura media</span><span class=\"t\" lang=\"pt\">Temperatura média</span><span class=\"t\" lang=\"fr\">Température moyenne</span><span class=\"t\" lang=\"ar\">متوسط الحرارة</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">16.7 days</span><span class=\"t\" lang=\"hi\">16.7 दिन</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Day</span><span class=\"t\" lang=\"hi\">दिन</span><span class=\"t\" lang=\"es\">Día</span><span class=\"t\" lang=\"pt\">Dia</span><span class=\"t\" lang=\"fr\">Jour</span><span class=\"t\" lang=\"ar\">اليوم</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">16.7 days</span><span class=\"t\" lang=\"hi\">16.7 दिन</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">One orbit</span><span class=\"t\" lang=\"hi\">एक परिक्रमा</span><span class=\"t\" lang=\"es\">Una órbita</span><span class=\"t\" lang=\"pt\">Uma órbita</span><span class=\"t\" lang=\"fr\">Une orbite</span><span class=\"t\" lang=\"ar\">مدار واحد</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">778.5 million km</span><span class=\"t\" lang=\"hi\">778.5 मिलियन किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Distance from the Sun</span><span class=\"t\" lang=\"hi\">सूर्य से दूरी</span><span class=\"t\" lang=\"es\">Distancia al Sol</span><span class=\"t\" lang=\"pt\">Distância do Sol</span><span class=\"t\" lang=\"fr\">Distance du Soleil</span><span class=\"t\" lang=\"ar\">البعد عن الشمس</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">1,882,700 km</span><span class=\"t\" lang=\"hi\">18,82,700 किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Distance from Jupiter</span><span class=\"t\" lang=\"hi\">बृहस्पति से दूरी</span><span class=\"t\" lang=\"es\">Distancia a Júpiter</span><span class=\"t\" lang=\"pt\">Distância de Júpiter</span><span class=\"t\" lang=\"fr\">Distance de Jupiter</span><span class=\"t\" lang=\"ar\">البعد عن المشتري</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">≈ 0 bar</span><span class=\"t\" lang=\"hi\">≈ 0 bar</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Surface pressure</span><span class=\"t\" lang=\"hi\">सतह का दबाव</span><span class=\"t\" lang=\"es\">Presión en la superficie</span><span class=\"t\" lang=\"pt\">Pressão na superfície</span><span class=\"t\" lang=\"fr\">Pression à la surface</span><span class=\"t\" lang=\"ar\">الضغط على السطح</span></span></div></div><h3><span class=\"t\" lang=\"en\">When and how it formed</span><span class=\"t\" lang=\"hi\">कब और कैसे बना</span></h3><div class=\"formhead\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">About 4.6 billion years ago, with Jupiter</span><span class=\"t\" lang=\"hi\">लगभग 4.6 अरब साल पहले, बृहस्पति के साथ</span></b><span><span class=\"t\" lang=\"en\">Formed</span><span class=\"t\" lang=\"hi\">कब बना</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">Slowly, perhaps over a million years or more</span><span class=\"t\" lang=\"hi\">धीरे-धीरे, शायद 10 लाख साल या ज़्यादा</span></b><span><span class=\"t\" lang=\"en\">How long it took</span><span class=\"t\" lang=\"hi\">कितना समय लगा</span></span></div></div><p><span class=\"t\" lang=\"en\">Callisto formed farthest out among Jupiter&amp;#x27;s big moons and grew slowly, so it never got hot enough to fully separate rock from ice. It is not squeezed by tides, so its surface is the oldest and most cratered in the solar system.</span><span class=\"t\" lang=\"hi\">Callisto बृहस्पति के बड़े चाँदों में सबसे दूर बना और धीरे-धीरे बढ़ा, इसलिए यह कभी इतना गर्म नहीं हुआ कि चट्टान और बर्फ़ पूरी तरह अलग हो सकें। इस पर ज्वारीय दबाव नहीं पड़ता, इसलिए इसकी सतह सौरमंडल की सबसे पुरानी और सबसे ज़्यादा गड्ढों वाली है।</span></p><div class=\"tl formtl\"><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">First million years or more</span><span class=\"t\" lang=\"hi\">पहले 10 लाख साल या ज़्यादा</span></div><p><span class=\"t\" lang=\"en\">Rock and ice slowly gather in the outer part of Jupiter&amp;#x27;s disk.</span><span class=\"t\" lang=\"hi\">बृहस्पति की disk के बाहरी हिस्से में चट्टान और बर्फ़ धीरे-धीरे जुड़ते हैं।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">About 4 billion years ago</span><span class=\"t\" lang=\"hi\">लगभग 4 अरब साल पहले</span></div><p><span class=\"t\" lang=\"en\">Heavy bombardment covers it in craters, including the giant Valhalla basin.</span><span class=\"t\" lang=\"hi\">भारी बमबारी इसे गड्ढों से ढक देती है, जिसमें विशाल Valhalla गड्ढा भी है।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Since then</span><span class=\"t\" lang=\"hi\">तब से</span></div><p><span class=\"t\" lang=\"en\">Almost unchanged; Galileo found signs of a salty ocean deep inside.</span><span class=\"t\" lang=\"hi\">लगभग बदला नहीं; Galileo को गहराई में खारे समुद्र के संकेत मिले।</span></p></div></div><p class=\"note\"><span class=\"t\" lang=\"en\">All dates are estimates from meteorites, moon rocks, space missions and computer models.</span><span class=\"t\" lang=\"hi\">सभी तारीख़ें अनुमान हैं, जो उल्कापिंडों, चाँद की चट्टानों, अंतरिक्ष missions और computer models से आती हैं।</span></p><h3><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Did you know?</span><span class=\"t\" lang=\"hi\">क्या आप जानते हैं?</span><span class=\"t\" lang=\"es\">¿Sabías que…?</span><span class=\"t\" lang=\"pt\">Você sabia?</span><span class=\"t\" lang=\"fr\">Le saviez-vous ?</span><span class=\"t\" lang=\"ar\">هل تعلم؟</span></h3><ul class=\"sheetfacts\"><li><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Callisto is one of the most heavily cratered places in the solar system, and its surface is very old.</span><span class=\"t\" lang=\"hi\">कैलिस्टो सौरमंडल की सबसे ज़्यादा गड्ढों वाली जगहों में से एक है, और उसकी सतह बहुत पुरानी है।</span><span class=\"t\" lang=\"es\">Calisto es uno de los lugares con más cráteres del sistema solar, y su superficie es muy antigua.</span><span class=\"t\" lang=\"pt\">Calisto é um dos lugares com mais crateras do Sistema Solar, e sua superfície é muito antiga.</span><span class=\"t\" lang=\"fr\">Callisto est l&#x27;un des endroits les plus criblés de cratères du système solaire, et sa surface est très ancienne.</span><span class=\"t\" lang=\"ar\">كاليستو من أكثر الأماكن ازدحامًا بالحفر في المجموعة الشمسية، وسطحه قديم جدًا.</span></li><li><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Callisto is far enough from Jupiter to get less of its harsh radiation, so scientists have suggested it for a future base.</span><span class=\"t\" lang=\"hi\">कैलिस्टो बृहस्पति से इतनी दूर है कि उसे उसका कठोर विकिरण कम मिलता है, इसलिए वैज्ञानिकों ने भविष्य के अड्डे के लिए उसका सुझाव दिया है।</span><span class=\"t\" lang=\"es\">Calisto está lo bastante lejos de Júpiter como para recibir menos de su dura radiación, por eso los científicos lo han propuesto para una futura base.</span><span class=\"t\" lang=\"pt\">Calisto fica longe o bastante de Júpiter para receber menos de sua radiação intensa, por isso cientistas o sugeriram para uma futura base.</span><span class=\"t\" lang=\"fr\">Callisto est assez loin de Jupiter pour recevoir moins de son rayonnement violent, c&#x27;est pourquoi des scientifiques l&#x27;ont proposée pour une future base.</span><span class=\"t\" lang=\"ar\">يبعد كاليستو عن المشتري بما يكفي ليتلقى إشعاعه القاسي بقدر أقل، ولذلك اقترحه العلماء لقاعدة مستقبلية.</span></li></ul><p><a class=\"btn primary\" href=\"body/callisto.html\" data-full><span class=\"t\" lang=\"en\">Full page: layers, telescope view, atmosphere</span><span class=\"t\" lang=\"hi\">पूरा page: परतें, दूरबीन का दृश्य, वायुमंडल</span> →</a></p>"},"titan":{"head":"<div class=\"sheethead\"><img class=\"pimg\" src=\"img/planets/titan.webp\" alt=\"Titan\" width=\"600\" height=\"600\" loading=\"eager\" decoding=\"async\"><div><h2 id=\"sheetTitle\"><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Titan</span><span class=\"t\" lang=\"hi\">टाइटन</span><span class=\"t\" lang=\"es\">Titán</span><span class=\"t\" lang=\"pt\">Titã</span><span class=\"t\" lang=\"fr\">Titan</span><span class=\"t\" lang=\"ar\">تيتان</span></h2><p class=\"sub\"><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Moon of Saturn</span><span class=\"t\" lang=\"hi\">शनि का चंद्रमा</span><span class=\"t\" lang=\"es\">Luna de Saturno</span><span class=\"t\" lang=\"pt\">Lua de Saturno</span><span class=\"t\" lang=\"fr\">Lune de Saturne</span><span class=\"t\" lang=\"ar\">قمر زحل</span></p></div></div>","body":"<div class=\"stats\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">5,150 km</span><span class=\"t\" lang=\"hi\">5,150 किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Diameter</span><span class=\"t\" lang=\"hi\">व्यास</span><span class=\"t\" lang=\"es\">Diámetro</span><span class=\"t\" lang=\"pt\">Diâmetro</span><span class=\"t\" lang=\"fr\">Diamètre</span><span class=\"t\" lang=\"ar\">القطر</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">1.4 m/s² (0.14 g)</span><span class=\"t\" lang=\"hi\">1.4 m/s² (0.14 g)</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Gravity</span><span class=\"t\" lang=\"hi\">गुरुत्वाकर्षण</span><span class=\"t\" lang=\"es\">Gravedad</span><span class=\"t\" lang=\"pt\">Gravidade</span><span class=\"t\" lang=\"fr\">Gravité</span><span class=\"t\" lang=\"ar\">الجاذبية</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">-179 °C</span><span class=\"t\" lang=\"hi\">-179 °C</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Average temperature</span><span class=\"t\" lang=\"hi\">औसत तापमान</span><span class=\"t\" lang=\"es\">Temperatura media</span><span class=\"t\" lang=\"pt\">Temperatura média</span><span class=\"t\" lang=\"fr\">Température moyenne</span><span class=\"t\" lang=\"ar\">متوسط الحرارة</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">15.9 days</span><span class=\"t\" lang=\"hi\">15.9 दिन</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Day</span><span class=\"t\" lang=\"hi\">दिन</span><span class=\"t\" lang=\"es\">Día</span><span class=\"t\" lang=\"pt\">Dia</span><span class=\"t\" lang=\"fr\">Jour</span><span class=\"t\" lang=\"ar\">اليوم</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">15.9 days</span><span class=\"t\" lang=\"hi\">15.9 दिन</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">One orbit</span><span class=\"t\" lang=\"hi\">एक परिक्रमा</span><span class=\"t\" lang=\"es\">Una órbita</span><span class=\"t\" lang=\"pt\">Uma órbita</span><span class=\"t\" lang=\"fr\">Une orbite</span><span class=\"t\" lang=\"ar\">مدار واحد</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">1,432 million km</span><span class=\"t\" lang=\"hi\">1,432 मिलियन किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Distance from the Sun</span><span class=\"t\" lang=\"hi\">सूर्य से दूरी</span><span class=\"t\" lang=\"es\">Distancia al Sol</span><span class=\"t\" lang=\"pt\">Distância do Sol</span><span class=\"t\" lang=\"fr\">Distance du Soleil</span><span class=\"t\" lang=\"ar\">البعد عن الشمس</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">1,221,900 km</span><span class=\"t\" lang=\"hi\">12,21,900 किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Distance from Saturn</span><span class=\"t\" lang=\"hi\">शनि से दूरी</span><span class=\"t\" lang=\"es\">Distancia a Saturno</span><span class=\"t\" lang=\"pt\">Distância de Saturno</span><span class=\"t\" lang=\"fr\">Distance de Saturne</span><span class=\"t\" lang=\"ar\">البعد عن زحل</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">1.45 bar</span><span class=\"t\" lang=\"hi\">1.45 bar</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Surface pressure</span><span class=\"t\" lang=\"hi\">सतह का दबाव</span><span class=\"t\" lang=\"es\">Presión en la superficie</span><span class=\"t\" lang=\"pt\">Pressão na superfície</span><span class=\"t\" lang=\"fr\">Pression à la surface</span><span class=\"t\" lang=\"ar\">الضغط على السطح</span></span></div></div><h3><span class=\"t\" lang=\"en\">When and how it formed</span><span class=\"t\" lang=\"hi\">कब और कैसे बना</span></h3><div class=\"formhead\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">About 4.6 billion years ago, with Saturn</span><span class=\"t\" lang=\"hi\">लगभग 4.6 अरब साल पहले, शनि के साथ</span></b><span><span class=\"t\" lang=\"en\">Formed</span><span class=\"t\" lang=\"hi\">कब बना</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">Within the first few million years</span><span class=\"t\" lang=\"hi\">पहले कुछ लाख साल में</span></b><span><span class=\"t\" lang=\"en\">How long it took</span><span class=\"t\" lang=\"hi\">कितना समय लगा</span></span></div></div><p><span class=\"t\" lang=\"en\">Titan formed from rock and ice in the disk around Saturn. It is the only moon with a thick atmosphere, mostly nitrogen, which may have come from ammonia ice broken apart long ago. Today it has rain, rivers and lakes of liquid methane.</span><span class=\"t\" lang=\"hi\">Titan शनि के चारों ओर की disk में चट्टान और बर्फ़ से बना। यह अकेला चाँद है जिसकी हवा घनी है, ज़्यादातर nitrogen, जो शायद बहुत पहले टूटी ammonia बर्फ़ से आई। आज यहाँ तरल methane की बारिश, नदियाँ और झीलें हैं।</span></p><div class=\"tl formtl\"><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">First few million years</span><span class=\"t\" lang=\"hi\">पहले कुछ लाख साल</span></div><p><span class=\"t\" lang=\"en\">Rock and ice gather into a moon bigger than Mercury.</span><span class=\"t\" lang=\"hi\">चट्टान और बर्फ़ जुड़कर बुध से बड़ा चाँद बनाते हैं।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Early on (unsure)</span><span class=\"t\" lang=\"hi\">शुरुआत में (पक्का नहीं)</span></div><p><span class=\"t\" lang=\"en\">Its thick nitrogen air forms, perhaps from ammonia in its ice.</span><span class=\"t\" lang=\"hi\">इसकी घनी nitrogen हवा बनती है, शायद इसकी बर्फ़ की ammonia से।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Today</span><span class=\"t\" lang=\"hi\">आज</span></div><p><span class=\"t\" lang=\"en\">Methane rain fills lakes near the poles; an ocean of water lies deep below the ice.</span><span class=\"t\" lang=\"hi\">methane की बारिश ध्रुवों के पास झीलें भरती है; बर्फ़ के नीचे गहराई में पानी का समुद्र है।</span></p></div></div><div class=\"callout\">❓ <b><span class=\"t\" lang=\"en\">Still unknown</span><span class=\"t\" lang=\"hi\">अभी भी अनजाना</span>:</b> <span class=\"t\" lang=\"en\">Where Titan&amp;#x27;s methane comes from, since sunlight keeps destroying it, is still a puzzle. NASA&amp;#x27;s Dragonfly drone is due to arrive in 2034.</span><span class=\"t\" lang=\"hi\">Titan का methane कहाँ से आता है, जबकि सूरज की रोशनी उसे लगातार तोड़ती है, यह अभी पहेली है। NASA का Dragonfly drone 2034 में पहुँचेगा।</span></div><p class=\"note\"><span class=\"t\" lang=\"en\">All dates are estimates from meteorites, moon rocks, space missions and computer models.</span><span class=\"t\" lang=\"hi\">सभी तारीख़ें अनुमान हैं, जो उल्कापिंडों, चाँद की चट्टानों, अंतरिक्ष missions और computer models से आती हैं।</span></p><h3><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Did you know?</span><span class=\"t\" lang=\"hi\">क्या आप जानते हैं?</span><span class=\"t\" lang=\"es\">¿Sabías que…?</span><span class=\"t\" lang=\"pt\">Você sabia?</span><span class=\"t\" lang=\"fr\">Le saviez-vous ?</span><span class=\"t\" lang=\"ar\">هل تعلم؟</span></h3><ul class=\"sheetfacts\"><li><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Titan is the only moon with a thick atmosphere. Its air pressure at the surface is higher than on Earth.</span><span class=\"t\" lang=\"hi\">टाइटन अकेला चंद्रमा है जिसका वायुमंडल घना है। उसकी सतह पर हवा का दबाव पृथ्वी से ज़्यादा है।</span><span class=\"t\" lang=\"es\">Titán es la única luna con una atmósfera densa. Su presión del aire en la superficie es mayor que en la Tierra.</span><span class=\"t\" lang=\"pt\">Titã é a única lua com atmosfera densa. A pressão do ar na superfície é maior que na Terra.</span><span class=\"t\" lang=\"fr\">Titan est la seule lune dotée d&#x27;une atmosphère épaisse. Sa pression de l&#x27;air en surface est supérieure à celle de la Terre.</span><span class=\"t\" lang=\"ar\">تيتان هو القمر الوحيد ذو الغلاف الجوي الكثيف. وضغط هوائه عند السطح أعلى منه على الأرض.</span></li><li><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Titan has rivers and lakes, but they hold liquid methane and ethane, not water.</span><span class=\"t\" lang=\"hi\">टाइटन पर नदियाँ और झीलें हैं, पर उनमें पानी नहीं, तरल मीथेन और ईथेन है।</span><span class=\"t\" lang=\"es\">Titán tiene ríos y lagos, pero contienen metano y etano líquidos, no agua.</span><span class=\"t\" lang=\"pt\">Titã tem rios e lagos, mas eles contêm metano e etano líquidos, não água.</span><span class=\"t\" lang=\"fr\">Titan a des rivières et des lacs, mais ils contiennent du méthane et de l&#x27;éthane liquides, pas de l&#x27;eau.</span><span class=\"t\" lang=\"ar\">في تيتان أنهار وبحيرات، لكنها تحتوي ميثانًا وإيثانًا سائلين لا ماءً.</span></li></ul><p><a class=\"btn primary\" href=\"body/titan.html\" data-full><span class=\"t\" lang=\"en\">Full page: layers, telescope view, atmosphere</span><span class=\"t\" lang=\"hi\">पूरा page: परतें, दूरबीन का दृश्य, वायुमंडल</span> →</a></p>"},"enceladus":{"head":"<div class=\"sheethead\"><img class=\"pimg\" src=\"img/planets/enceladus.webp\" alt=\"Enceladus\" width=\"600\" height=\"600\" loading=\"eager\" decoding=\"async\"><div><h2 id=\"sheetTitle\"><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Enceladus</span><span class=\"t\" lang=\"hi\">एन्सेलेडस</span><span class=\"t\" lang=\"es\">Encélado</span><span class=\"t\" lang=\"pt\">Encélado</span><span class=\"t\" lang=\"fr\">Encelade</span><span class=\"t\" lang=\"ar\">إنسيلادوس</span></h2><p class=\"sub\"><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Moon of Saturn</span><span class=\"t\" lang=\"hi\">शनि का चंद्रमा</span><span class=\"t\" lang=\"es\">Luna de Saturno</span><span class=\"t\" lang=\"pt\">Lua de Saturno</span><span class=\"t\" lang=\"fr\">Lune de Saturne</span><span class=\"t\" lang=\"ar\">قمر زحل</span></p></div></div>","body":"<div class=\"stats\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">504 km</span><span class=\"t\" lang=\"hi\">504 किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Diameter</span><span class=\"t\" lang=\"hi\">व्यास</span><span class=\"t\" lang=\"es\">Diámetro</span><span class=\"t\" lang=\"pt\">Diâmetro</span><span class=\"t\" lang=\"fr\">Diamètre</span><span class=\"t\" lang=\"ar\">القطر</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">0.1 m/s² (0.01 g)</span><span class=\"t\" lang=\"hi\">0.1 m/s² (0.01 g)</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Gravity</span><span class=\"t\" lang=\"hi\">गुरुत्वाकर्षण</span><span class=\"t\" lang=\"es\">Gravedad</span><span class=\"t\" lang=\"pt\">Gravidade</span><span class=\"t\" lang=\"fr\">Gravité</span><span class=\"t\" lang=\"ar\">الجاذبية</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">-198 °C</span><span class=\"t\" lang=\"hi\">-198 °C</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Average temperature</span><span class=\"t\" lang=\"hi\">औसत तापमान</span><span class=\"t\" lang=\"es\">Temperatura media</span><span class=\"t\" lang=\"pt\">Temperatura média</span><span class=\"t\" lang=\"fr\">Température moyenne</span><span class=\"t\" lang=\"ar\">متوسط الحرارة</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">32.9 h</span><span class=\"t\" lang=\"hi\">32.9 घंटे</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Day</span><span class=\"t\" lang=\"hi\">दिन</span><span class=\"t\" lang=\"es\">Día</span><span class=\"t\" lang=\"pt\">Dia</span><span class=\"t\" lang=\"fr\">Jour</span><span class=\"t\" lang=\"ar\">اليوم</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">1.4 days</span><span class=\"t\" lang=\"hi\">1.4 दिन</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">One orbit</span><span class=\"t\" lang=\"hi\">एक परिक्रमा</span><span class=\"t\" lang=\"es\">Una órbita</span><span class=\"t\" lang=\"pt\">Uma órbita</span><span class=\"t\" lang=\"fr\">Une orbite</span><span class=\"t\" lang=\"ar\">مدار واحد</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">1,432 million km</span><span class=\"t\" lang=\"hi\">1,432 मिलियन किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Distance from the Sun</span><span class=\"t\" lang=\"hi\">सूर्य से दूरी</span><span class=\"t\" lang=\"es\">Distancia al Sol</span><span class=\"t\" lang=\"pt\">Distância do Sol</span><span class=\"t\" lang=\"fr\">Distance du Soleil</span><span class=\"t\" lang=\"ar\">البعد عن الشمس</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">238,000 km</span><span class=\"t\" lang=\"hi\">2,38,000 किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Distance from Saturn</span><span class=\"t\" lang=\"hi\">शनि से दूरी</span><span class=\"t\" lang=\"es\">Distancia a Saturno</span><span class=\"t\" lang=\"pt\">Distância de Saturno</span><span class=\"t\" lang=\"fr\">Distance de Saturne</span><span class=\"t\" lang=\"ar\">البعد عن زحل</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">≈ 0 bar</span><span class=\"t\" lang=\"hi\">≈ 0 bar</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Surface pressure</span><span class=\"t\" lang=\"hi\">सतह का दबाव</span><span class=\"t\" lang=\"es\">Presión en la superficie</span><span class=\"t\" lang=\"pt\">Pressão na superfície</span><span class=\"t\" lang=\"fr\">Pression à la surface</span><span class=\"t\" lang=\"ar\">الضغط على السطح</span></span></div></div><h3><span class=\"t\" lang=\"en\">When and how it formed</span><span class=\"t\" lang=\"hi\">कब और कैसे बना</span></h3><div class=\"formhead\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">With Saturn, about 4.6 billion years ago (some think later)</span><span class=\"t\" lang=\"hi\">शनि के साथ, लगभग 4.6 अरब साल पहले (कुछ के अनुसार बाद में)</span></b><span><span class=\"t\" lang=\"en\">Formed</span><span class=\"t\" lang=\"hi\">कब बना</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">Unknown</span><span class=\"t\" lang=\"hi\">पक्का नहीं</span></b><span><span class=\"t\" lang=\"en\">How long it took</span><span class=\"t\" lang=\"hi\">कितना समय लगा</span></span></div></div><p><span class=\"t\" lang=\"en\">Enceladus is a small moon of ice and rock. Tidal squeezing from Saturn heats it enough to keep a salty ocean under the south pole, which sprays water into space through cracks. Cassini flew through these jets and tasted salt and simple organic molecules.</span><span class=\"t\" lang=\"hi\">Enceladus बर्फ़ और चट्टान का छोटा चाँद है। शनि का ज्वारीय दबाव इसे इतना गर्म करता है कि दक्षिणी ध्रुव के नीचे खारा समुद्र तरल रहता है, जो दरारों से पानी अंतरिक्ष में उछालता है। Cassini इन धाराओं के बीच से उड़ा और उसे नमक और सरल organic अणु मिले।</span></p><div class=\"tl formtl\"><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">4.6 billion years ago (or later)</span><span class=\"t\" lang=\"hi\">4.6 अरब साल पहले (या बाद में)</span></div><p><span class=\"t\" lang=\"en\">Ice and rock gather into a small moon.</span><span class=\"t\" lang=\"hi\">बर्फ़ और चट्टान जुड़कर एक छोटा चाँद बनाते हैं।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Over time</span><span class=\"t\" lang=\"hi\">समय के साथ</span></div><p><span class=\"t\" lang=\"en\">Tidal heating melts a global ocean under the ice shell.</span><span class=\"t\" lang=\"hi\">ज्वारीय गर्मी बर्फ़ की परत के नीचे पूरा समुद्र पिघला देती है।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Today</span><span class=\"t\" lang=\"hi\">आज</span></div><p><span class=\"t\" lang=\"en\">More than 100 geysers spray from the &amp;quot;tiger stripes&amp;quot;; the spray feeds Saturn&amp;#x27;s E ring.</span><span class=\"t\" lang=\"hi\">&amp;quot;tiger stripes&amp;quot; से 100 से ज़्यादा फव्वारे उछलते हैं; यही फुहार शनि के E ring को भरती है।</span></p></div></div><div class=\"callout\">❓ <b><span class=\"t\" lang=\"en\">Still unknown</span><span class=\"t\" lang=\"hi\">अभी भी अनजाना</span>:</b> <span class=\"t\" lang=\"en\">Some models say Saturn&amp;#x27;s mid-sized moons, Enceladus among them, are only about 100 million years old. Others say they are as old as Saturn. It is not settled.</span><span class=\"t\" lang=\"hi\">कुछ models कहते हैं कि शनि के मँझले चाँद, Enceladus भी, बस लगभग 10 करोड़ साल पुराने हैं। दूसरे कहते हैं वे शनि जितने पुराने हैं। यह तय नहीं है।</span></div><p class=\"note\"><span class=\"t\" lang=\"en\">All dates are estimates from meteorites, moon rocks, space missions and computer models.</span><span class=\"t\" lang=\"hi\">सभी तारीख़ें अनुमान हैं, जो उल्कापिंडों, चाँद की चट्टानों, अंतरिक्ष missions और computer models से आती हैं।</span></p><h3><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Did you know?</span><span class=\"t\" lang=\"hi\">क्या आप जानते हैं?</span><span class=\"t\" lang=\"es\">¿Sabías que…?</span><span class=\"t\" lang=\"pt\">Você sabia?</span><span class=\"t\" lang=\"fr\">Le saviez-vous ?</span><span class=\"t\" lang=\"ar\">هل تعلم؟</span></h3><ul class=\"sheetfacts\"><li><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Enceladus shoots jets of ice and water vapour into space through cracks near its south pole.</span><span class=\"t\" lang=\"hi\">एन्सेलेडस अपने दक्षिणी ध्रुव के पास की दरारों से बर्फ़ और जलवाष्प की धाराएँ अंतरिक्ष में छोड़ता है।</span><span class=\"t\" lang=\"es\">Encélado lanza chorros de hielo y vapor de agua al espacio por grietas cercanas a su polo sur.</span><span class=\"t\" lang=\"pt\">Encélado lança jatos de gelo e vapor de água no espaço por rachaduras perto do polo sul.</span><span class=\"t\" lang=\"fr\">Encelade projette des jets de glace et de vapeur d&#x27;eau dans l&#x27;espace par des fissures près de son pôle sud.</span><span class=\"t\" lang=\"ar\">يطلق إنسيلادوس نفاثات من الجليد وبخار الماء إلى الفضاء عبر شقوق قرب قطبه الجنوبي.</span></li><li><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">The jets of Enceladus feed Saturn&#x27;s E ring.</span><span class=\"t\" lang=\"hi\">एन्सेलेडस की ये धाराएँ शनि के E छल्ले को भरती हैं।</span><span class=\"t\" lang=\"es\">Los chorros de Encélado alimentan el anillo E de Saturno.</span><span class=\"t\" lang=\"pt\">Os jatos de Encélado alimentam o anel E de Saturno.</span><span class=\"t\" lang=\"fr\">Les jets d&#x27;Encelade alimentent l&#x27;anneau E de Saturne.</span><span class=\"t\" lang=\"ar\">تغذي نفاثات إنسيلادوس حلقة زحل E.</span></li></ul><p><a class=\"btn primary\" href=\"body/enceladus.html\" data-full><span class=\"t\" lang=\"en\">Full page: layers, telescope view, atmosphere</span><span class=\"t\" lang=\"hi\">पूरा page: परतें, दूरबीन का दृश्य, वायुमंडल</span> →</a></p>"},"triton":{"head":"<div class=\"sheethead\"><img class=\"pimg\" src=\"img/planets/triton.webp\" alt=\"Triton\" width=\"600\" height=\"600\" loading=\"eager\" decoding=\"async\"><div><h2 id=\"sheetTitle\"><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Triton</span><span class=\"t\" lang=\"hi\">ट्राइटन</span><span class=\"t\" lang=\"es\">Tritón</span><span class=\"t\" lang=\"pt\">Tritão</span><span class=\"t\" lang=\"fr\">Triton</span><span class=\"t\" lang=\"ar\">تريتون</span></h2><p class=\"sub\"><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Moon of Neptune</span><span class=\"t\" lang=\"hi\">वरुण का चंद्रमा</span><span class=\"t\" lang=\"es\">Luna de Neptuno</span><span class=\"t\" lang=\"pt\">Lua de Netuno</span><span class=\"t\" lang=\"fr\">Lune de Neptune</span><span class=\"t\" lang=\"ar\">قمر نبتون</span></p></div></div>","body":"<div class=\"stats\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">2,707 km</span><span class=\"t\" lang=\"hi\">2,707 किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Diameter</span><span class=\"t\" lang=\"hi\">व्यास</span><span class=\"t\" lang=\"es\">Diámetro</span><span class=\"t\" lang=\"pt\">Diâmetro</span><span class=\"t\" lang=\"fr\">Diamètre</span><span class=\"t\" lang=\"ar\">القطر</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">0.8 m/s² (0.08 g)</span><span class=\"t\" lang=\"hi\">0.8 m/s² (0.08 g)</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Gravity</span><span class=\"t\" lang=\"hi\">गुरुत्वाकर्षण</span><span class=\"t\" lang=\"es\">Gravedad</span><span class=\"t\" lang=\"pt\">Gravidade</span><span class=\"t\" lang=\"fr\">Gravité</span><span class=\"t\" lang=\"ar\">الجاذبية</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">-235 °C</span><span class=\"t\" lang=\"hi\">-235 °C</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Average temperature</span><span class=\"t\" lang=\"hi\">औसत तापमान</span><span class=\"t\" lang=\"es\">Temperatura media</span><span class=\"t\" lang=\"pt\">Temperatura média</span><span class=\"t\" lang=\"fr\">Température moyenne</span><span class=\"t\" lang=\"ar\">متوسط الحرارة</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">5.9 days</span><span class=\"t\" lang=\"hi\">5.9 दिन</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Day</span><span class=\"t\" lang=\"hi\">दिन</span><span class=\"t\" lang=\"es\">Día</span><span class=\"t\" lang=\"pt\">Dia</span><span class=\"t\" lang=\"fr\">Jour</span><span class=\"t\" lang=\"ar\">اليوم</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">5.9 days</span><span class=\"t\" lang=\"hi\">5.9 दिन</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">One orbit</span><span class=\"t\" lang=\"hi\">एक परिक्रमा</span><span class=\"t\" lang=\"es\">Una órbita</span><span class=\"t\" lang=\"pt\">Uma órbita</span><span class=\"t\" lang=\"fr\">Une orbite</span><span class=\"t\" lang=\"ar\">مدار واحد</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">4,515 million km</span><span class=\"t\" lang=\"hi\">4,515 मिलियन किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Distance from the Sun</span><span class=\"t\" lang=\"hi\">सूर्य से दूरी</span><span class=\"t\" lang=\"es\">Distancia al Sol</span><span class=\"t\" lang=\"pt\">Distância do Sol</span><span class=\"t\" lang=\"fr\">Distance du Soleil</span><span class=\"t\" lang=\"ar\">البعد عن الشمس</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">354,800 km</span><span class=\"t\" lang=\"hi\">3,54,800 किमी</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Distance from Neptune</span><span class=\"t\" lang=\"hi\">वरुण से दूरी</span><span class=\"t\" lang=\"es\">Distancia a Neptuno</span><span class=\"t\" lang=\"pt\">Distância de Netuno</span><span class=\"t\" lang=\"fr\">Distance de Neptune</span><span class=\"t\" lang=\"ar\">البعد عن نبتون</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">&lt; 0.001 bar</span><span class=\"t\" lang=\"hi\">&lt; 0.001 bar</span></b><span><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Surface pressure</span><span class=\"t\" lang=\"hi\">सतह का दबाव</span><span class=\"t\" lang=\"es\">Presión en la superficie</span><span class=\"t\" lang=\"pt\">Pressão na superfície</span><span class=\"t\" lang=\"fr\">Pression à la surface</span><span class=\"t\" lang=\"ar\">الضغط على السطح</span></span></div></div><h3><span class=\"t\" lang=\"en\">When and how it formed</span><span class=\"t\" lang=\"hi\">कब और कैसे बना</span></h3><div class=\"formhead\"><div class=\"stat\"><b><span class=\"t\" lang=\"en\">In the Kuiper Belt about 4.6 billion years ago; captured later</span><span class=\"t\" lang=\"hi\">लगभग 4.6 अरब साल पहले Kuiper Belt में; बाद में पकड़ा गया</span></b><span><span class=\"t\" lang=\"en\">Formed</span><span class=\"t\" lang=\"hi\">कब बना</span></span></div><div class=\"stat\"><b><span class=\"t\" lang=\"en\">Unknown</span><span class=\"t\" lang=\"hi\">पक्का नहीं</span></b><span><span class=\"t\" lang=\"en\">How long it took</span><span class=\"t\" lang=\"hi\">कितना समय लगा</span></span></div></div><p><span class=\"t\" lang=\"en\">Triton did not form around Neptune. It goes around Neptune backwards, which a moon born there would not do, so it was probably a dwarf planet like Pluto that Neptune captured. The capture heated and reshaped it.</span><span class=\"t\" lang=\"hi\">Triton नेपच्यून के चारों ओर नहीं बना। यह नेपच्यून के चारों ओर उल्टी दिशा में घूमता है, जो वहाँ जन्मा चाँद नहीं करता, इसलिए यह शायद प्लूटो जैसा बौना ग्रह था जिसे नेपच्यून ने पकड़ लिया। पकड़े जाने से यह गर्म हुआ और इसका रूप बदला।</span></p><div class=\"tl formtl\"><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">4.6 billion years ago</span><span class=\"t\" lang=\"hi\">4.6 अरब साल पहले</span></div><p><span class=\"t\" lang=\"en\">It forms in the Kuiper Belt, perhaps as one of a pair of bodies.</span><span class=\"t\" lang=\"hi\">यह Kuiper Belt में बनता है, शायद दो पिंडों की जोड़ी में से एक।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Later (unknown when)</span><span class=\"t\" lang=\"hi\">बाद में (कब, पता नहीं)</span></div><p><span class=\"t\" lang=\"en\">Neptune captures it into a backwards orbit; tides heat it.</span><span class=\"t\" lang=\"hi\">नेपच्यून इसे उल्टी कक्षा में पकड़ लेता है; ज्वार इसे गर्म करते हैं।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">Today</span><span class=\"t\" lang=\"hi\">आज</span></div><p><span class=\"t\" lang=\"en\">Voyager 2 (1989) saw nitrogen geysers and a young surface.</span><span class=\"t\" lang=\"hi\">Voyager 2 (1989) ने nitrogen के फव्वारे और नई सतह देखी।</span></p></div><div class=\"m\"><div class=\"y\"><span class=\"t\" lang=\"en\">In billions of years</span><span class=\"t\" lang=\"hi\">अरबों साल बाद</span></div><p><span class=\"t\" lang=\"en\">Its orbit slowly shrinks; Neptune&amp;#x27;s gravity may tear it into a ring.</span><span class=\"t\" lang=\"hi\">इसकी कक्षा धीरे-धीरे छोटी होगी; नेपच्यून की gravity शायद इसे तोड़कर छल्ला बना दे।</span></p></div></div><p class=\"note\"><span class=\"t\" lang=\"en\">All dates are estimates from meteorites, moon rocks, space missions and computer models.</span><span class=\"t\" lang=\"hi\">सभी तारीख़ें अनुमान हैं, जो उल्कापिंडों, चाँद की चट्टानों, अंतरिक्ष missions और computer models से आती हैं।</span></p><h3><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Did you know?</span><span class=\"t\" lang=\"hi\">क्या आप जानते हैं?</span><span class=\"t\" lang=\"es\">¿Sabías que…?</span><span class=\"t\" lang=\"pt\">Você sabia?</span><span class=\"t\" lang=\"fr\">Le saviez-vous ?</span><span class=\"t\" lang=\"ar\">هل تعلم؟</span></h3><ul class=\"sheetfacts\"><li><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">Triton goes around Neptune backwards, so it was probably a dwarf planet that Neptune captured.</span><span class=\"t\" lang=\"hi\">ट्राइटन वरुण का चक्कर उल्टी दिशा में लगाता है, इसलिए शायद वह एक बौना ग्रह था जिसे वरुण ने पकड़ लिया।</span><span class=\"t\" lang=\"es\">Tritón gira alrededor de Neptuno al revés, así que probablemente era un planeta enano que Neptuno capturó.</span><span class=\"t\" lang=\"pt\">Tritão gira em torno de Netuno ao contrário, então provavelmente era um planeta anão capturado por Netuno.</span><span class=\"t\" lang=\"fr\">Triton tourne autour de Neptune à l&#x27;envers, c&#x27;était donc probablement une planète naine capturée par Neptune.</span><span class=\"t\" lang=\"ar\">يدور تريتون حول نبتون في الاتجاه المعاكس، لذا ربما كان كوكبًا قزمًا أسره نبتون.</span></li><li><span class=\"t\" lang=\"en\" data-tr=\"es pt fr ar\">At about −235 °C, Triton is one of the coldest places anyone has measured in the solar system.</span><span class=\"t\" lang=\"hi\">करीब −235 °C पर ट्राइटन सौरमंडल की उन सबसे ठंडी जगहों में है जहाँ कभी तापमान नापा गया है।</span><span class=\"t\" lang=\"es\">A unos −235 °C, Tritón es uno de los lugares más fríos que se han medido en el sistema solar.</span><span class=\"t\" lang=\"pt\">A cerca de −235 °C, Tritão é um dos lugares mais frios já medidos no Sistema Solar.</span><span class=\"t\" lang=\"fr\">À environ −235 °C, Triton est l&#x27;un des endroits les plus froids jamais mesurés dans le système solaire.</span><span class=\"t\" lang=\"ar\">عند نحو −235 °C يُعد تريتون من أبرد الأماكن التي قيست في المجموعة الشمسية.</span></li></ul><p><a class=\"btn primary\" href=\"body/triton.html\" data-full><span class=\"t\" lang=\"en\">Full page: layers, telescope view, atmosphere</span><span class=\"t\" lang=\"hi\">पूरा page: परतें, दूरबीन का दृश्य, वायुमंडल</span> →</a></p>"}};